schemas.schema-01-systematic.prisma:
/// Channel entity - Implements requirements from the Extensibility & System Structure and System Overview documents. Represents a logical or physical interface/medium (such as web, mobile, kiosk) through which users interact with the AI Shopmall. Maintains 3NF normalization by separating channel metadata from section/business logic. For example, creating a channel entry for 'mobile app' versus 'in-store kiosk'. Key relationships: referenced by sections, configurations, or analytics modules. Special behaviors: Channel codes must be unique and static for integration; deletion is forbidden if referenced by a section or configuration.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each channel.
  id String @id @db.Uuid

  /// Unique short code for the channel (e.g., WEB, MOBILE, KIOSK). For example: 'WEB' for website channel. Ensures normalization by preventing duplicated names/codes in reference tables. Must be unique.
  code String

  /// Display name of the channel (e.g., Website, Mobile App). Used for user/admin interfaces. Maintains separation of display label from internal codes. For example, 'Mobile App' for the app channel.
  name String

  /// Detailed description or notes about the channel. For example, specify device compatibility, language restrictions, or features unique to this channel. Nullable as some channels may not require description.
  description String?

  /// Creation timestamp. Implements auditability requirements. Used for tracking the introduction of a channel without inferring meaning from id ordering.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp. 3NF compliance by storing update moment distinctly. Enables audit and rollback operations.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shopmall_sections       ai_shopmall_sections[]
  ai_shopmall_configurations ai_shopmall_configurations[]

  @@unique([code])
  @@index([created_at])
}

/// Section entity - Implements requirements from Extensibility & System Structure for mapping logical/functional subdivisions within a channel (e.g., Product List, Cart, Admin Panel). Business Purpose: Organizes the system by functionality per channel, enabling extensibility and permission controls. Maintains 3NF by separating sections from business data and meta-configurations. For example, a 'Cart' section in 'Mobile App' or 'Admin Section' in 'Web'. Key relationships: May reference ai_shopmall_channels via foreign key. Special behaviors: Names must be unique within each channel; UI may hide or restrict access by section code.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each section.
  id String @id @db.Uuid

  /// Belonged channel's {@link ai_shopmall_channels.id}. Enforces that each section is mapped to a specific channel for organizational and permission management purposes.
  channel_id String @db.Uuid

  /// Unique code for the section within the channel (e.g., PRODUCT_LIST, CART) - Implements business logic for UI routing or permission mapping. Ensures no duplicated codes for a channel. For example: 'CART' for the shopping cart section.
  code String

  /// Display label for the section (e.g., Cart, Orders, Analytics Dashboard). User/admin-facing for menu and navigation. Ensures separation from unique code for human-readable display.
  name String

  /// Detailed description or business notes for the section - Explains the role or special permissions related to the section. Nullable as not all sections require extended info.
  description String?

  /// Timestamp when the section was created. Required for audit and rollback, complying with audit log requirements.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  channel ai_shopmall_channels @relation(fields: [channel_id], references: [id], onDelete: Cascade)

  ai_shopmall_configurations ai_shopmall_configurations[]

  @@unique([channel_id, code])
  @@index([channel_id])
  @@index([created_at])
}

/// Configuration entity - Implements requirements for central configuration storage from Extensibility & System Structure and System Overview. System/business configurations are stored here and optionally scoped by channel/section. Maintains 3NF by separating configuration values from operational data. For example: storing feature toggles, app settings, enablement flags. Key relationships: Optionally references ai_shopmall_channels and ai_shopmall_sections if configs are channel/section-specific. Special behaviors: Code is globally unique unless scoped by channel/section; key lookup supports multilevel fallback (e.g., section > channel > global).
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique ID for each configuration entry.
  id String @id @db.Uuid

  /// Optional referencing channel's {@link ai_shopmall_channels.id}. Distinguishes configs scoped by channel. Nullable to allow global or section-only configs.
  channel_id String? @db.Uuid

  /// Optional referencing section's {@link ai_shopmall_sections.id}. Distinguishes configs scoped by section. Nullable for channel-level or global configs.
  section_id String? @db.Uuid

  /// Unique configuration code or key (e.g., ENABLE_CART, FEATURE_BULK_UPLOAD). Implements robust settings access pattern. Must be unique for the same channel/section scope. For example: 'PROMO_BANNER_ENABLED'.
  code String

  /// Configuration value (stringified for flexibility, e.g., true, 10, "feature-x", or JSON). Maintains normalization by keeping one value per config key per section/channel/global context. For example: 'true' for enabled feature, '{"max":5}' for JSON settings. Type parsing/validation is application responsibility.
  value String

  /// Explanation or business note for the configuration entry (optional). Nullable; for admin-facing context.
  description String?

  /// Creation timestamp. For historical audits and rollback support.
  created_at DateTime @db.Timestamptz

  /// Last modification time.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  channel ai_shopmall_channels? @relation(fields: [channel_id], references: [id], onDelete: Cascade)
  section ai_shopmall_sections? @relation(fields: [section_id], references: [id], onDelete: Cascade)

  @@unique([code, channel_id, section_id])
  @@index([channel_id])
  @@index([section_id])
  @@index([created_at])
}

/// Attachment entity - Implements the requirements for extensible, versioned file/asset attachments from Extensibility & System Structure. Stores logical references to files used across modules (e.g., product images, manuals, review attachments). Maintains 3NF by separating file reference metadata from file content/data (which is stored in ai_shopmall_files). For example: a product review attachment references the actual blob/file by file_id, but is an independent entity for meta and versioning. Key relationships: References ai_shopmall_files. Special behaviors: Each attachment must have a unique UUID; deletion should check if in use in referencing modules (e.g., reviews, products).
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each attachment.
  id String @id @db.Uuid

  /// Referenced file blob's {@link ai_shopmall_files.id}. Associates attachment record to physical file/data. Non-nullable for strict referential integrity.
  file_id String @db.Uuid

  /// Entity table/type code to which this attachment belongs (e.g., PRODUCT, REVIEW, USER, BULLETIN). Implements polymorphic referencing in a normalized way. For example: 'REVIEW' for review attachment. Not a foreign key for normalization separation.
  entity_type String

  /// Referenced entity's UUID (e.g., productId, reviewId, userId). Enables logical association while maintaining 3NF - the link to target entity is always a UUID. For example: a file attached to review with reviewId = '...'.
  entity_id String @db.Uuid

  /// Attachment display name or label (e.g., 'receipt', 'user-avatar.png'). Used for admin/user preview, can be edited. Not necessarily unique for usage flexibility.
  name String

  /// Version number of the attachment for update/audit trail. Implements simple version control, preserves old versions for rollback/history. For example, version increments on re-upload of same file for the same entity.
  version Int @db.Integer

  /// Attachment creation timestamp. For audit trails and ordering versions.
  created_at DateTime @db.Timestamptz

  /// Latest attachment update timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  file ai_shopmall_files @relation(fields: [file_id], references: [id], onDelete: Cascade)

  ai_shopmall_product_images ai_shopmall_product_images[]

  @@unique([entity_type, entity_id, name, version])
  @@index([entity_type, entity_id])
  @@index([file_id])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// File entity - Stores and manages the actual binary/file/blob references, as required by the Extensibility & System Structure. Decoupled from attachments for reusability and separation of version/audit logic. Maintains 3NF by not embedding multiple files or blobs, but by linking one file to multiple attachments as needed. For example: image, document, or video file record; may be reused in multiple entities by referencing attachments. Special behaviors: Files should not be deleted unless all referencing attachments are purged; audit logs must record access/modification; URI must be unique.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_files {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each file.
  id String @id @db.Uuid

  /// Storage URI or blob key, e.g. S3/GCS/MinIO/Local path. Implements file access controls and uniqueness. For example: 's3://bucket/abc123' or 'files/2025/07/img015.png'. Must be unique.
  uri String @db.VarChar(80000)

  /// Original or assigned filename - For audit and user previews. For example: 'manual.pdf', 'avatar_001.png'. Display only; not required to be unique.
  name String

  /// File size in bytes. For business rules limiting upload size and for audit. Ensures integrity by reflecting actual data size.
  size Int @db.Integer

  /// MIME type of the file (e.g., 'image/png', 'application/pdf'). Used for preview/render restrictions and validation. Ensures compliance and normalization by not hardcoding type elsewhere.
  mime_type String

  /// Timestamp when the file record was created (not when file was uploaded). For audit traceability and storage lifecycle policies.
  created_at DateTime @db.Timestamptz

  /// Timestamp of latest file info update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shopmall_attachments ai_shopmall_attachments[]

  @@unique([uri])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Plugin module entity - Implements the extensibility concept from Extensibility & System Structure, providing the system with a way to reference loaded/available plugin modules by settings and code. Maintains 3NF by centralizing module references apart from operational/setting data. For example, a payment plugin, analytics module, or UI extension module could be represented here. Key relationships: Potential foreign keys (not implemented here) to settings/configuration snapshots. Special behaviors: Codes must be unique and static for integration and dependency resolution.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_plugin_modules {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for plugin module.
  id String @id @db.Uuid

  /// Unique plugin module code (e.g., 'PAYMENT_STRIPE', 'PROMO_ENGINE'). For internal/programmatic referencing and dependency checks. Must be unique.
  code String

  /// Display label for the plugin module. Used in admin UIs, module browsers.
  name String

  /// Detailed description of the plugin/module function. For admin/business notes and integration guidance. Nullable for basic modules.
  description String?

  /// Semantic version string of the plugin/module (e.g., '1.0.0', '2.4.1-beta'). Implements dependency/version compatibility rules. Not enforced by DB, but parsed by application logic.
  version String

  /// JSON-schema describing module settings structure. Enables validation and UI generation for module config. Normalization: settings are not stored here, only schema/structure is. For example: '{"type":"object","properties":{"api_key":...}}'.
  settings_schema String

  /// Timestamp plugin module was registered.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for plugin module info.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([code])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-02-actors.prisma:
/// Customer Account Entity - This implements the requirements for shopper accounts (AI Shopmall User and Identity Management, Section 3 & 4). Captures unique customer user details (separate from sellers and admins), including registration, status, and relationship to core profile. Maintains strict 3NF normalization by separating role/persona details from profile and authentication. For example, when a new user registers as a customer, this model is used to persist their system identity as a customer only. Key relationships: Links to ai_shopmall_user_profiles (profile), ai_shopmall_user_roles (role claim), and addresses (delivery/contact info). Special behaviors: Role is fixed to 'customer'; can be upgraded (with additional registration) to seller/admin but never mixed at row level.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique customer account UUID.
  id String @id @db.Uuid

  /// Belonged user profile's {@link ai_shopmall_user_profiles.id}. Binds this customer to a core profile with contact and personal info.
  user_profile_id String @db.Uuid

  /// Customer account's primary email - Implements customer registration requirement; used for contact, login, and notifications. Strictly unique. Example: customer1@example.com. Normalization: atomic, not derived.
  email String

  /// Current customer account status. Implements activation/ban logic (Section 4). Business meaning: 'active', 'pending', 'banned', or 'deleted'. Used for audit, access management. Ensures atomicity.
  status String

  /// Account creation timestamp - Implements audit and history tracking requirement. Normalization: atomic. Example: 2025-07-22T13:06:55Z.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp - Implements modification audit requirement. Updated on every non-read change. Example: 2025-07-22T13:06:55Z.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profiles_fk ai_shopmall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  ai_shopmall_carts                    ai_shopmall_carts[]
  ai_shopmall_orders                   ai_shopmall_orders[]
  ai_shopmall_returns                  ai_shopmall_returns[]
  ai_shopmall_coupon_issuances         ai_shopmall_coupon_issuances[]
  ai_shopmall_reward_histories         ai_shopmall_reward_histories[]
  ai_shopmall_mileages                 ai_shopmall_mileages?
  ai_shopmall_fraud_activities         ai_shopmall_fraud_activities[]
  ai_shopmall_analytic_profiles        ai_shopmall_analytic_profiles[]
  ai_shopmall_reviews                  ai_shopmall_reviews[]
  ai_shopmall_review_likes             ai_shopmall_review_likes[]
  ai_shopmall_review_reports           ai_shopmall_review_reports[]
  ai_shopmall_ratings                  ai_shopmall_ratings[]
  ai_shopmall_questions                ai_shopmall_questions[]
  ai_shopmall_comments                 ai_shopmall_comments[]
  ai_shopmall_engagement_logs          ai_shopmall_engagement_logs[]
  ai_shopmall_favorites                ai_shopmall_favorites[]
  ai_shopmall_favorite_folders         ai_shopmall_favorite_folders[]
  ai_shopmall_notification_preferences ai_shopmall_notification_preferences[]
  ai_shopmall_user_permissions         ai_shopmall_user_permissions[]
  ai_shopmall_access_logs              ai_shopmall_access_logs[]
  ai_shopmall_security_events          ai_shopmall_security_events[]
  ai_shopmall_policy_acceptances       ai_shopmall_policy_acceptances[]
  ai_shopmall_data_retention_logs      ai_shopmall_data_retention_logs[]

  @@unique([email])
  @@unique([user_profile_id])
  @@index([status])
}

/// Seller Account Entity - Implements requirements for commerce-side actor onboarding (see User and Identity Management, Seller section, seller approval flow). Captures unique seller user records, registration status, approval links, and role isolation. Normalization is maintained by having one core profile per seller, linked with ai_shopmall_user_profiles. When a user applies to become a seller, a record here is created, approval status/state is managed here, and all seller-specific management (stores, inventory) references this entity. Key relationships: ai_shopmall_user_profiles (identity), ai_shopmall_user_roles (role/privilege), ai_shopmall_addresses (business/contact address). Special behaviors: Enforces admin-approval logic, 'pending'/'approved'/'rejected' status.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique seller UUID.
  id String @id @db.Uuid

  /// Belonged user profile's {@link ai_shopmall_user_profiles.id}.
  user_profile_id String @db.Uuid

  /// Seller account email - Implements seller registration, notifications, and authentication. Unique per seller. Example: seller42@store.com. Ensures normalized, atomic contact identity.
  email String

  /// Seller approval workflow status. Implements business process for onboarding ('pending', 'approved', 'rejected', 'banned'). Used for enabling/disabling access. Strictly atomic. For example, on application, set as 'pending', moves to 'approved' when admin confirms.
  approval_status String

  /// Time of record creation. Implements onboarding audit. Updated only on create.
  created_at DateTime @db.Timestamptz

  /// Time of last modification. Implements seller management history audit. Updated on profile/permission change.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profiles_fk ai_shopmall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  ai_shopmall_seller_products ai_shopmall_seller_products[]
  ai_shopmall_answers         ai_shopmall_answers[]

  @@unique([email])
  @@unique([user_profile_id])
  @@index([approval_status])
}

/// Administrator Account Entity - Implements privileged user account requirement (Section 3 User Roles, Section 6 Security/Compliance). Captures user-admin records and allows permission management, non-public role tracking, and restricted access to management features. Separation from customer/seller ensures proper RBAC architecture. Only one admin role per person, mapped to ai_shopmall_user_profiles. Key relationships: ai_shopmall_user_profiles (identity), ai_shopmall_user_roles (role binding). Special behaviors: Admin role requires explicit assignation, audit-logged.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_administrators {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique admin user UUID.
  id String @id @db.Uuid

  /// Belonged user profile's {@link ai_shopmall_user_profiles.id}.
  user_profile_id String @db.Uuid

  /// Administrator account's email - Implements privileged login, notifications. Must be unique and official/email domain-restricted. Ensures atomicity. Example: admin@shopmall.com.
  email String

  /// Administrative access scope. Implements compliance between "system", "support", "auditor" or custom RBAC labels. Used to determine admin rights.
  access_level String

  /// Account creation time. Used for system onboarding audit. Normalization: atomic timestamp. Example: 2025-07-22T13:06:55Z.
  created_at DateTime @db.Timestamptz

  /// Time of last record update (used for edit audit trail, status change).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profiles_fk ai_shopmall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  ai_shopmall_order_status_histories ai_shopmall_order_status_histories[]
  ai_shopmall_order_snapshots        ai_shopmall_order_snapshots[]
  ai_shopmall_promotion_snapshots    ai_shopmall_promotion_snapshots[]
  ai_shopmall_bulletins              ai_shopmall_bulletins[]
  ai_shopmall_moderation_actions     ai_shopmall_moderation_actions[]

  @@unique([email])
  @@unique([user_profile_id])
  @@index([access_level])
}

/// User Profile Entity - Implements centralized profile storage for actor types (Section 5, Profile Management). Stores user's display name, avatar, personal contact data, and preferences in atomic, normalized columns. Shared by all roles via foreign key. Used on registration, OAuth attachment, or when editing personal details. Maintains 3NF by avoiding role-specific fields here. Key relationships: Referenced by ai_shopmall_customers, ai_shopmall_sellers, ai_shopmall_administrators as profile FK. Special behaviors: Only demographic and contact details live here; no credentials or sensitive tokens.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_user_profiles {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique user profile UUID.
  id String @id @db.Uuid

  /// User chosen display name - Implements personalization and recognition. Example: 'Shopper2025'. Atomic, not derived.
  display_name String

  /// Profile picture URI - Used for personalization/avatar display. Normalized as atomic URI string.
  avatar_url String? @db.VarChar(80000)

  /// User's contact phone - Used for notification or verification, always atomic. Example: '+82 10 1234-5678'.
  phone String?

  /// Profile creation timestamp. Implements audit/compliance requirements. Example: 2025-07-22T13:06:55Z.
  created_at DateTime @db.Timestamptz

  /// Profile last modification time - Required for change tracking.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shopmall_customers      ai_shopmall_customers?
  ai_shopmall_sellers        ai_shopmall_sellers?
  ai_shopmall_administrators ai_shopmall_administrators?
  ai_shopmall_user_roles     ai_shopmall_user_roles[]
  ai_shopmall_oauth_accounts ai_shopmall_oauth_accounts[]
  ai_shopmall_addresses      ai_shopmall_addresses[]
  ai_shopmall_sessions       ai_shopmall_sessions[]
  ai_shopmall_audit_logs     ai_shopmall_audit_logs[]

  @@unique([display_name])
  @@index([created_at])
}

/// User Role Entity - Implements role management and escalation/approval logic (Section 7, RBAC design in requirements). Supports assignment of "customer", "seller", "admin", and further role expansions. Normalized mapping between user_profile and current role/permissions. Each actor type row links back to this table to trace privileges. Used on login, permission check, and role upgrade/demotion flows. Key relationships: ai_shopmall_user_profiles (user), referenced by actor tables for RBAC mapping. Special behaviors: One record per user/role combination, unique enforced.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_user_roles {
  //----
  // COLUMNS
  //----
  /// Primary Key. User-Role mapping UUID.
  id String @id @db.Uuid

  /// Associated user profile's {@link ai_shopmall_user_profiles.id}.
  user_profile_id String @db.Uuid

  /// Role name/type - Implements RBAC claim mapping (e.g., 'customer', 'seller', 'admin', or custom). Atomic. Example usage: grant user 'seller' after approval flow.
  role String

  /// Approval status for escalated roles - Implements audit/authorization flow (needed for sellers/admins). True if role is active and operational. Example: False for applicant, True when admin approves escalation.
  approved Boolean

  /// Mapping creation timestamp. Maintains audit chain for RBAC. Example: 2025-07-22T13:06:55Z.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profiles_fk ai_shopmall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  @@unique([user_profile_id, role])
  @@index([role])
}

/// OAuth Account Link Entity - Implements external authentication connection and OAuth provider profile mapping (Section 4, OAuth). Stores per-user per-provider tokens/accounts. Used when users connect or register via Google, Apple, Kakao, Naver (etc.). Maintains strict separation (1NF/3NF) by not storing private token fields except provider/user/simple metadata. Primary usage: login/registration, plus unlink/refresh token workflows. Key relationships: ai_shopmall_user_profiles (profile FK). 1:N possible (user may have many providers). Special behaviors: Only stores minimal OAuth identity (not actual access token values, for security).
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_oauth_accounts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique OAuth linkage UUID.
  id String @id @db.Uuid

  /// Associated user profile's {@link ai_shopmall_user_profiles.id}, owner of this OAuth account.
  user_profile_id String @db.Uuid

  /// OAuth provider identifier - Implements provider management (e.g., 'google', 'apple', 'kakao', 'naver'). Atomic, normalized. Used to display serialization/workflow choices.
  provider String

  /// Provider-side user identity/claims - Implements mapping requirement. For Google, this is 'sub'; Apple, 'user'; etc. Strictly atomic, never stores tokens.
  provider_user_id String

  /// OAuth-linked email - Used to match/verify user identity (never used standalone in customer table; always atomically stored).
  email String

  /// When this OAuth was attached. Used for timeline and audit purposes. Example: 2025-07-22T13:06:55Z.
  linked_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profiles_fk ai_shopmall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  @@unique([provider, provider_user_id])
  @@index([user_profile_id])
  @@index([email(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// User Address Entity - Implements normalized, multi-address management per user (Section 5, Profile, Shipping, Notification addresses). Stores multiple address book entries per user profile (e.g., home, work, recent), avoids denormalization by separating per-address into row. Used at checkout, for shipping/fulfillment automation, and notification preference context. Key relationships: ai_shopmall_user_profiles (foreign FK, owner), reference from order/fulfillment subdomains. Special behaviors: 1 user can have many addresses (1:N), can be tagged 'primary'.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_addresses {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique address UUID.
  id String @id @db.Uuid

  /// Owner user profile's {@link ai_shopmall_user_profiles.id}.
  user_profile_id String @db.Uuid

  /// Address label for recognition - Implements convenience for users managing multiple addresses (e.g., 'Home', 'Work'). Not derived. Atomic.
  label String

  /// Recipient's actual name - Used on shipping documents, tracking, etc. Atomic, not derived. Example: 'Kim Minji'.
  recipient_name String

  /// Recipient/contact phone - Needed for delivery and notification. Only the phone for this address (not user's main phone). Atomic. Example: '+82 10-9876-5432'.
  phone String

  /// Post/zip code of address. Used for quick validation and shipping fees. Atomic. Example: '06109'. Not calculated/derived.
  postal_code String

  /// Main address line (street address, building). Fulfills shipping and geolocation requirements.
  address_line1 String

  /// Secondary/detailed address (suite, floor, etc.), optional. Atomic, not split.
  address_line2 String?

  /// City/locality - Atomic for regional/routing, not derived. Example: 'Seoul'.
  city String

  /// Province/region/state - Needed for shipping, fees, and legal reqs. Example: 'Gangnam-gu' or 'CA'.
  province String

  /// Country code/name. Used at checkout for internationalization. e.g., 'KR', 'US', 'JP'. Always atomic.
  country String

  /// Whether this is the user's primary/default address. Used for preselecting in checkout/delivery. Only one can be true per user.
  primary Boolean

  /// Address record creation time. For audit logs and address history.
  created_at DateTime @db.Timestamptz

  /// Address last modification time - Maintains atomic change log for address management.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profiles_fk ai_shopmall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  @@unique([user_profile_id, label])
  @@index([postal_code])
  @@index([label(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// User/Auth Session Entity - Implements login state, refresh session/cookie management (Section 4, Session/Token Management). Each successful login creates a session, tracks device, expiry, and audit trail. Not holding access tokens directly, only ids/fingerprints/session hashes. Used in multi-device login and concurrent session management. (Atomic, normalized, 3NF.) Key relationships: ai_shopmall_user_profiles (owner/user). Cross-referenced by audit logs, permission escalations. Special behaviors: Automatic expiry/invalidating on logout/inactivity.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique session UUID.
  id String @id @db.Uuid

  /// Owner user profile's {@link ai_shopmall_user_profiles.id}.
  user_profile_id String @db.Uuid

  /// Opaque, secure session string (never actual JWT, just system-issued session handle). Used for session validation. Example: 'sess_24U86'.
  session_token String

  /// Device/browser fingerprint hash - Used for multi-device security audits. Atomic, not derived. Example: 'fp:hks8l2z18u'.
  device_fingerprint String?

  /// Login IP address. Used for geo-fencing/audit. Example: '175.112.53.14'.
  ip_address String

  /// Session expiry timestamp. Implements session/hard expiry policies. Example: 2025-08-01T13:06:55Z.
  expires_at DateTime @db.Timestamptz

  /// Session record creation time - Used for session audit trails.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profiles_fk ai_shopmall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  ai_shopmall_audit_logs ai_shopmall_audit_logs[]

  @@unique([session_token])
  @@index([user_profile_id])
  @@index([expires_at])
}

/// User/Actor Audit Log Entity - Implements compliance and traceability (Section 6, Security and Compliance; Section 4 Traceability). Captures every sensitive/critical actor operation: login, logout, permission changes, profile updates, role escalations, etc. Normalized fields: actor_id, event_type, timestamp, detail (atomic/audit-level data). Used for legal/compliance queries, admin/support dashboards. Key relationships: ai_shopmall_user_profiles (actor), ai_shopmall_sessions (session). Special behaviors: System must write a row for every sensitive action, append-only.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique audit log entry UUID.
  id String @id @db.Uuid

  /// Actor user profile's {@link ai_shopmall_user_profiles.id}.
  user_profile_id String @db.Uuid

  /// Session during which event occurred. References {@link ai_shopmall_sessions.id}.
  session_id String? @db.Uuid

  /// Log event type - Implements audit categories: 'login', 'logout', 'role_update', 'profile_edit', etc. Used for filtering and compliance queries.
  event_type String

  /// Free-form event payload/metadata. Used for investigation/context, always atomic (never derived). Example: JSON string with changed fields, IP, reason, etc.
  event_detail String?

  /// Timestamp of audit log entry creation - Immutable; must not be changed after insert.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user_profiles_fk ai_shopmall_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)
  sessions_fk      ai_shopmall_sessions?     @relation(fields: [session_id], references: [id], onDelete: Cascade)

  @@index([session_id])
  @@index([user_profile_id])
  @@index([created_at])
  @@index([event_type(ops: raw("gin_trgm_ops"))], type: Gin)
}

