schemas.schema-04-carts_orders_fulfillment.prism:
/// Shopping cart entity - Implements shopping cart management from Order, Cart & Fulfillment. Allows one cart per customer or guest session. Maintains strict normalization and uses proper referential integrity to customers.
///
/// @namespace CartsOrdersFulfillment
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_carts {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_shopmall_customers.id}. Links this cart to a registered customer. Nullable for guest carts.
  ai_shopmall_customer_id String? @db.Uuid

  /// For guest carts: session key; unique among guest carts. Nullable for registered customers.
  session_token String?

  /// Timestamp of cart creation (audit trail).
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp; tracks logical deletes for audit/compliance.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  CartToCustomer ai_shopmall_customers? @relation(fields: [ai_shopmall_customer_id], references: [id], onDelete: Cascade)

  ai_shopmall_cart_items ai_shopmall_cart_items[]
  ai_shopmall_orders     ai_shopmall_orders[]

  @@unique([session_token])
  @@unique([ai_shopmall_customer_id])
}

/// Cart item entity - Each record is a unique SKU in a cart. No denormalization; all calculated data is deferred to materialized views. Enforces uniqueness per SKU per cart.
///
