  /// Link to parent cart's {@link ai_shopmall_carts.id}.
  ai_shopmall_cart_id String @db.Uuid

  /// Link to product variant (SKU) {@link ai_shopmall_product_variants.id}.
  ai_shopmall_product_variant_id String @db.Uuid

  /// Number of units chosen for this SKU. Atomic value; aggregation deferred.
  quantity Int @db.Integer

  /// JSON string of selected options/properties (e.g., size, color).
  selected_options String?

  /// Date/time when added to cart.
  added_at DateTime @db.Timestamptz

