schemas.schema-05-promotions_coupons_rewards.pri:
/// Promotion Rule Definition - This implements the master promotion campaign entity requirement from the Promotions & Rewards Requirements. Handles all promo rule configurations, eligibility settings, business properties, targeting criteria, time windows, and audit-trail linking for campaign management. Maintains full 3NF normalization by splitting targets, issuances, and historical impact to related tables. Used for: Creating and editing promotions (campaign manager), setting rules for associated coupons/rewards, analytics linking, and fraud pattern auditing. Key relationships: coupons, targets, snapshots. Special behaviors: changing rule causes snapshot save and propagation to associated entities.
///
/// @namespace PromotionsCouponsRewards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_promotions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Promotion name - Implements campaign identification and display. Required for administrator and analytics reference. Example: 'Black Friday Flash'.
  name String

  /// Extended human-readable description and campaign rules. Explains business logic and what user segments/targets this applies to. Used for admin review, documentation, and analytics. Example: '10% off for selected electronics. Not stackable with other offers.'
  description String?

  /// Rule engine type identifier (e.g., 'coupon', 'price_discount', 'bundle', 'loyalty'). Implements targeting and discount logic assignment per requirements. Example: 'coupon'.
  rule_type String

  /// Whether this promotion rule is actively available for evaluation and use. Implements enable/disable control for campaign timing (required to prevent accidental stacking). Example: true.
  active Boolean

  /// The datetime when this promotion becomes active. Controls time-bound eligibility for campaign logic. Required for detailed analytics/reporting and legal compliance. Example: 2025-10-10T00:00:00Z.
  starts_at DateTime @db.Timestamptz

  /// The datetime when this promotion expires. Defined for blackout/expiry logic, audit trail, and to ensure campaign limits. Example: 2025-10-20T23:59:59Z.
  ends_at DateTime? @db.Timestamptz

  /// Row creation timestamp for audit trail and temporal tracking. Ensures data lineage and 3NF compliance.
  created_at DateTime @db.Timestamptz

  /// Row last-modified timestamp for change tracking. Enables snapshot-based audit trail and normalization.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shopmall_coupons             ai_shopmall_coupons[]
  ai_shopmall_promotion_targets   ai_shopmall_promotion_targets[]
  ai_shopmall_promotion_snapshots ai_shopmall_promotion_snapshots[]

  @@unique([name])
  @@index([active])
  @@index([starts_at])
}

/// Concrete Coupon Definition - Implements the requirement for flexible, multi-type coupon instances linked to promotions. Defines coupon code, type, issue/expiry windows, stacking rules, target entity types (product/category/channel), and maximum usage constraints. Maintains 3NF by separating issuance, histories, and links to master promotion. Used for: Seller/administrator issuing campaigns, API validation of user-applied coupons, reporting, and end-user wallet display. Key relationships: Linked to ai_shopmall_promotions and ai_shopmall_coupon_issuances. Special behavior: Cannot be directly stacked unless rule allows.
///
/// @namespace PromotionsCouponsRewards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_coupons {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to parent promotion {@link ai_shopmall_promotions.id}. Defines which promotion campaign this coupon belongs to. Required for campaign assignment and eligibility lookups.
  promotion_id String @db.Uuid

  /// Coupon code string (for user/app input). Enforces format and uniqueness. Used to validate redemption and for analytics. Example: 'BF2025VIP'.
  code String

  /// Coupon type identifier. Examples: 'percentage', 'fixed', 'product', 'category', 'shipping'. Used for business logic at apply-time (required per requirements analysis). Example: 'percentage'.
  coupon_type String

  /// Coupon issuance timestamp. Used for control/lifecycle/analytics. Example: 2025-07-01T10:00:00Z.
  issued_at DateTime @db.Timestamptz

  /// Coupon expiry timestamp. Required for lifecycle, eligibility, and compliance logic. Null if no explicit expiration. Example: 2025-10-31T23:59:59Z.
  expires_at DateTime? @db.Timestamptz

  /// Maximum allowed redemptions for this coupon (per-coupon limit). Fulfills requirement for preventing fraud/abuse. Example: 1000.
  max_uses Int? @db.Integer

  /// Is this coupon exclusive (mutually exclusive stack)? Required for promo stacking logic enforcement. Example: false.
  exclusive Boolean

  /// Enables/disables this coupon for redemption. Used to suspend or resume coupon regardless of start/end timeframe. Example: true.
  active Boolean

  /// Row creation timestamp for audit trail and control.
  created_at DateTime @db.Timestamptz

  /// Row modification timestamp for full normalization and snapshot propagation.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shopmall_coupons_promotion_id ai_shopmall_promotions @relation(fields: [promotion_id], references: [id], onDelete: Cascade)

  ai_shopmall_coupon_issuances ai_shopmall_coupon_issuances[]

  @@unique([code])
  @@index([promotion_id])
  @@index([coupon_type])
}

/// Coupon Issuance Log - Implements the requirement for user-specific, single-use or multi-use coupon redemptions. Defines each issuance event, tracking to user/account (external FK), coupon, and order reference. Enables audit trail, eligibility history, per-user usage limits, and fraud detection links. Fully normalized (no redundant data; references only) and supports time-based reporting. Key relationships: Coupons, user entity (external table), related order (external table). Special constraints: Usage and status flags prevent double redemption.
///
/// @namespace PromotionsCouponsRewards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_coupon_issuances {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Issued coupon's {@link ai_shopmall_coupons.id}. Required for tracing which coupon was granted/applied.
  coupon_id String @db.Uuid

  /// Issued customer's {@link ai_shopmall_customers.id} (defined in Actors component). Enables user linkage for analytics and user wallet API. Business rule: one-to-many (single coupon can be issued to many users, but each issuance is for one user).
  customer_id String @db.Uuid

  /// Related {@link ai_shopmall_orders.id} indicating which order (if any) the coupon was used in. Used for analytics and audit logs. Nullable if not yet redeemed.
  order_id String? @db.Uuid

  /// Issuance/usage status. e.g., 'issued', 'used', 'expired', 'cancelled'. Supports full redemption workflow, analytics, and fraud checks.
  status String

  /// Coupon issued timestamp.
  issued_at DateTime @db.Timestamptz

  /// Coupon redemption timestamp (if used). Null until redeemed.
  used_at DateTime? @db.Timestamptz

  /// Explicit expiry time for this usage/issuance. Computes per issuance instance (not global coupon).
  expired_at DateTime? @db.Timestamptz

  /// Row creation timestamp (audit).
  created_at DateTime @db.Timestamptz

  /// Row update timestamp (normalization, control).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shopmall_coupon_issuances_coupon_id   ai_shopmall_coupons   @relation(fields: [coupon_id], references: [id], onDelete: Cascade)
  fk_ai_shopmall_coupon_issuances_customer_id ai_shopmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  fk_ai_shopmall_coupon_issuances_order_id    ai_shopmall_orders?   @relation(fields: [order_id], references: [id], onDelete: Cascade)

  @@unique([coupon_id, customer_id])
  @@index([customer_id])
  @@index([order_id])
  @@index([status])
}

/// Reward History - Implements accumulation, earning, and redemption history for mileage/point/deposit events. Each entry tracks the entity (user, via FK), event type (earn, redeem, expire), event source (order, review, etc.), and impacted mileage record. Maintains 3NF by referencing master tables only. Key relationships: mileage record, customer. Special behavior: entry must remain immutable for audit compliance.
///
/// @namespace PromotionsCouponsRewards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_reward_histories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner's {@link ai_shopmall_customers.id}. Maps mileage/reward action to user entity (Actors component).
  customer_id String @db.Uuid

  /// Referenced {@link ai_shopmall_mileages.id} record; history always linked to one mileage.
  mileage_id String @db.Uuid

  /// Related {@link ai_shopmall_orders.id} used in this reward/earn event. Null when not directly order-sourced.
  order_id String? @db.Uuid

  /// Type of event: 'earn','redeem','expire','rollback','manual_adjust'. Distinguishes accrual vs. deduction operations for reporting/auditing.
  event_type String

  /// What triggered this reward: e.g. 'order','review','refund','admin','promo'. For requirement trace and audit trail.
  event_source String

  /// Point/mileage/deposit value for this event. Always signed, non-cumulative (use for per-event reporting).
  value Float @db.DoublePrecision

  /// Timestamp of event occurrence (not always same as record creation for backdated/late events).
  event_at DateTime @db.Timestamptz

  /// Row insert timestamp (audit, normalization).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shopmall_reward_histories_customer_id ai_shopmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  fk_ai_shopmall_reward_histories_mileage_id  ai_shopmall_mileages  @relation(fields: [mileage_id], references: [id], onDelete: Cascade)
  fk_ai_shopmall_reward_histories_order_id    ai_shopmall_orders?   @relation(fields: [order_id], references: [id], onDelete: Cascade)

  @@index([customer_id])
  @@index([mileage_id])
  @@index([order_id])
  @@index([event_type])
}

/// Mileage/Point/Deposit Balances - Implements the requirement for real-time balances of user reward accounts. Separates cumulative, current balances from event log (full 3NF, no redundancy). Each mileage record ties directly to a user/customer, specifies mileage/reward type (e.g., 'point', 'deposit', 'cashback'), and holds only real-time, up-to-date balance. Audited strictly for financial/legal compliance; all changes tracked in ai_shopmall_reward_histories. Key usage: Mileage wallet API, admin control panel, order/checkout eligibility enforcement. Special constraint: No calculations or aggregates stored here except current balance; all history in histories table.
///
/// @namespace PromotionsCouponsRewards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_mileages {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner's {@link ai_shopmall_customers.id}. Mileage/reward balance always belongs to one user only.
  customer_id String @db.Uuid

  /// Balance type: e.g., 'point','deposit','cashback'. Enforces consistent accounting control (requirement).
  mileage_type String

  /// Current, real-time balance at this record (no roll-up or calculated values allowed here).
  balance Float @db.DoublePrecision

  /// Timestamp of last event affecting this balance (requirement: ensures up-to-date snapshot for eligibility and audits).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ai_shopmall_mileages_customer_id ai_shopmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  ai_shopmall_reward_histories ai_shopmall_reward_histories[]

  @@unique([customer_id])
  @@unique([customer_id, mileage_type])
  @@index([mileage_type])
}

/// Promotion Target Assignment - Implements external targeting for promotion rules. Assigns specific products, categories, users, or channels as eligible for a promotion in ai_shopmall_promotions. Fully normalized: references only target ids and types, never holding full entity data. Used for AI-driven targeting, eligibility checks, campaign analytics, and fraud prevention. Key relationships: ai_shopmall_promotions. Target ID/value corresponds to external table; type distinguishes which.
///
/// @namespace PromotionsCouponsRewards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_promotion_targets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to {@link ai_shopmall_promotions.id} defining assigned campaign.
  promotion_id String @db.Uuid

  /// Type of target entity ('product','category','customer','seller','channel'). Implements flexible targeting engine/requirement.
  target_type String

  /// ID of target entity (product, category, etc.; external FK to Products/Actors/etc). Null if target is by type or requires criteria-only matching.
  target_id String? @db.Uuid

  //----
  // RELATIONS
  //----
  fk_ai_shopmall_promotion_targets_promotion_id ai_shopmall_promotions @relation(fields: [promotion_id], references: [id], onDelete: Cascade)

  @@unique([promotion_id, target_type, target_id])
  @@index([target_type])
}

/// Promotion/Coupon Fraud Flagging - Implements detection, escalation, and audit of suspected promo/coupon fraud. Tracks flagged accounts, events, or entities, links to external entity by ID (user, order, coupon), maintains status/stage, and retains event context. Main purpose: satisfy fraud prevention, audit trail, compliance and real-time monitoring requirements. Key usage: Real-time fraud monitoring for redemptions, high-velocity usage, or abnormal stacking scenarios. Key relationships: may point to coupons, orders, users depending on flag.
///
/// @namespace PromotionsCouponsRewards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_fraud_flags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reason/type of flag (examples: 'abuse','velocity','multi_account','suspicious_redeem'). Must align with risk patterns extracted from requirements.
  flag_type String

  /// Reference entity type ('coupon','order','user','promotion','event'). Used for cross-module mapping and normalization.
  entity_type String

  /// External entity reference (must match entity_type's domain, e.g., order ID, coupon ID). Null if only entity type is tracked.
  entity_id String? @db.Uuid

  /// Flag status ('open','investigating','resolved','blocked'). Workflow ensures trace, audit, and compliance as per requirements.
  status String

  /// Flexible JSON or text holding event details for audit investigation, AI context, or manual review. Enables compliance traceability.
  context String?

  /// Timestamp when flag was issued. For compliance snapshots and monitoring.
  created_at DateTime @db.Timestamptz

  /// Flag state update timestamp. Required for legal audit trace and compliance logs.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([flag_type])
  @@index([status])
  @@index([context(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Promotion Snapshot - This implements the change history and audit record for each promotion definition, satisfying snapshot architecture and compliance requirement. Each record logs the full configuration of a promotion at the time of edit/change, storing all fields from ai_shopmall_promotions plus a reference to the original rule and the user/admin who edited. Maintains 3NF; no denormalized aggregates. Key relationships: ai_shopmall_promotions (origin), admin/user editor (external FK). Used for rollback, audit investigations, and compliance retention. Snapshots are append-only; never updated (only new versions are written).
///
/// @namespace PromotionsCouponsRewards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_promotion_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Back-reference to original promotion rule {@link ai_shopmall_promotions.id}. Defines which active campaign this is a version of (required for rollback and audit linkage).
  origin_promotion_id String @db.Uuid

  /// User/Admin who performed the change (FK to ai_shopmall_administrators in Actors component). Used for accountability and data lineage.
  editor_admin_id String @db.Uuid

  /// Promotion name at this version. Keeps history of all versions' titles. Example: 'Black Friday Flash - V2'.
  name String

  /// Full snapshot of description at change time. Used for investigation/audit.
  description String?

  /// Rule type as configured in parent promo at this snapshot point. Example: 'coupon'.
  rule_type String

  /// Whether this snapshot was active at time of edit. For operational and display audit. Example: true.
  active Boolean

  /// Activation window start at this version. Used for rollback and forensic controls.
  starts_at DateTime @db.Timestamptz

  /// End window as configured at last edit (nullable if open-ended).
  ends_at DateTime? @db.Timestamptz

  /// Time of snapshot record creation (mutation timestamp/audit trail).
  snapshot_at DateTime @db.Timestamptz

  /// Free-text log for what caused change (admin note, auto, backend, AI, etc). Used for audit, compliance, and forensic analysis.
  reason String?

  //----
  // RELATIONS
  //----
  fk_ai_shopmall_promotion_snapshots_origin_promotion_id ai_shopmall_promotions     @relation(fields: [origin_promotion_id], references: [id], onDelete: Cascade)
  fk_ai_shopmall_promotion_snapshots_editor_admin_id     ai_shopmall_administrators @relation(fields: [editor_admin_id], references: [id], onDelete: Cascade)

  @@index([editor_admin_id])
  @@index([origin_promotion_id])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-06-analytics_ai.prisma:
/// AI Recommendation results for users or sessions – Implements requirements from Analytics & AI Platform (requirementAnalysisReport, 06_ai_shopmall_ai_and_analytics_platform.md).
///
/// Business purpose: Stores top-N recommendation outcomes for users or sessions, categorized by scenario (e.g., homepage, product detail, campaign promo). Maintains strict 3NF normalization; only atomic fields and references. Example: logs that user X received product Y and Z suggestions on date T, with ranking scores.
///
/// Key relationships: References analytic_profile or user via foreign keys (customer or seller, from Actors), and products (from Products domain). Behavioral constraints: Must not denormalize product/title or user info, and must always preserve recommendation reason and scoring.
/// Special behaviors: Each entry belongs to a computation cycle (e.g. nightly batch or real-time), can be audited per recommendation engine version.
///
/// @namespace AnalyticsAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_ai_recommendations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each recommendation result.
  id String @id @db.Uuid

  /// Target user or analytic profile’s {@link ai_shopmall_analytic_profiles.id}. Represents the subject entity to whom the recommendation was made.
  analytic_profile_id String @db.Uuid

  /// Recommended product’s {@link ai_shopmall_products.id}. Points to a product in the master catalog.
  product_id String @db.Uuid

  /// Type or scenario for the recommendation (e.g., homepage, cross-sell, upsell, campaign). Fully normalized single atomic value per record. Example: 'homepage', 'detail_page', 'email_campaign'.
  recommendation_type String

  /// Ranking position of this product in the recommendation list (1 = highest). Atomic, required for repeatable evaluation.
  rank Int @db.Integer

  /// Numeric score assigned by the recommendation engine (not pre-calculated rank, but model output only). E.g. affinity or predicted CTR.
  score Float @db.DoublePrecision

  /// Human-readable reason, label or short classifier for why the item was recommended (e.g., 'Similar to X', 'Best sellers', 'Based on cart'). Not calculated aggregation – single cause only.
  reason String

  /// Version string of the recommendation model/algorithm that generated this entry. For audit and tracking. No aggregated summaries.
  engine_version String

  /// UTC timestamp when the recommendation was generated. Always required for auditability. Not aggregated.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  analytic_profile ai_shopmall_analytic_profiles @relation(fields: [analytic_profile_id], references: [id], onDelete: Cascade)
  product          ai_shopmall_products          @relation(fields: [product_id], references: [id], onDelete: Cascade)

  ai_shopmall_recommendation_logs ai_shopmall_recommendation_logs[]

  @@unique([analytic_profile_id, created_at, recommendation_type, product_id, rank])
  @@index([analytic_profile_id, created_at])
  @@index([product_id])
}

/// Fraud detection events per Analytics & AI requirements (see 06_ai_shopmall_ai_and_analytics_platform.md). Implements event-level abnormal/fraud activity logging for audits and intervention triggers.
///
/// Business purpose: Captures suspicious activities/transactions flagged by the AI fraud engine or anomaly detectors. Maintains 3NF: one record per unique activity/event per scan. Example: logs when an order is detected with abnormal purchase velocity or flagged as synthetic. Not a pre-calculated aggregate. No duplicate/roll-up fields allowed.
///
/// Key relationships: References analytic_event, user (from Actors), or entity IDs. Used by admins for incident review.
/// Special behaviors: Each entry is immutable for compliance and audit purposes.
///
/// @namespace AnalyticsAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_fraud_activities {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each fraud activity event.
  id String @id @db.Uuid

  /// Related event’s {@link ai_shopmall_analytic_events.id}. Connects this fraud incident to the originating analytic event record.
  analytic_event_id String @db.Uuid

  /// Optionally links to a user (customer, seller, admin) who triggered the activity. References {@link ai_shopmall_customers.id}, ai_shopmall_sellers.id, or ai_shopmall_administrators.id as needed. Kept fully normalized; only a single user reference per activity.
  user_id String? @db.Uuid

  /// Type/category of detected fraud or anomaly (e.g., payment_fraud, fake_review, velocity_attack, account_takeover). Atomic value only. No aggregated patterns.
  activity_type String

  /// Optional JSON or text describing the context/details of the fraud activity detected. E.g., device info, IP, AI model findings. Single event context only, not an aggregation.
  context_info String?

  /// Timestamp of fraud detection. Required, atomic and non-aggregated per row. UTC datetime only.
  detected_at DateTime @db.Timestamptz

  /// If this fraud activity was escalated for manual or admin review. Not pre-calculated rollup – atomic per event.
  is_escalated Boolean

  //----
  // RELATIONS
  //----
  analytic_event ai_shopmall_analytic_events @relation(fields: [analytic_event_id], references: [id], onDelete: Cascade)
  user           ai_shopmall_customers?      @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@unique([analytic_event_id, activity_type, detected_at])
  @@index([user_id])
  @@index([detected_at])
}

/// Raw analytic event log for Analytics & AI Platform. See requirements from analytic_events entity in 06_ai_shopmall_ai_and_analytics_platform.md.
///
/// Business purpose: Logs all fine-grained, atomic user or system events for subsequent AI analysis, insight dashboards, or real-time triggers. Examples: product_view, add_to_cart, purchase, page_visit, recommendation_clicked. 
///
/// Strict 3NF: Each record logs a single discrete event. Contains NO aggregates/summaries.
/// Key relationships: References analytic_profile, may reference user or related objects by ID only.
/// Special behaviors: Immutable; never roll up, summarize, or denormalize within this table.
///
/// @namespace AnalyticsAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_analytic_events {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each analytic event.
  id String @id @db.Uuid

  /// Subject’s {@link ai_shopmall_analytic_profiles.id}. Identifies user/session/actor for this event. Required, atomic.
  ///
  analytic_profile_id String @db.Uuid

  /// Atomic type of analytic event (e.g., product_view, add_to_cart, checkout, order_complete). No rollups. Business event only.
  event_type String

  /// Raw event payload, typically structured JSON or key-value string form. Must only include atomic event data for this row; never summary forms. For example: product_id, page, metadata.
  event_data String?

  /// UTC datetime when event occurred. Required for all events; not calculated.
  occurred_at DateTime @db.Timestamptz

  /// Optional – source of this event (e.g., web, mobile, api, batch). Single source only. Example: 'web'.
  source String?

  //----
  // RELATIONS
  //----
  analytic_profile ai_shopmall_analytic_profiles @relation(fields: [analytic_profile_id], references: [id], onDelete: Cascade)

  ai_shopmall_fraud_activities ai_shopmall_fraud_activities[]
  ai_shopmall_ai_alerts        ai_shopmall_ai_alerts[]

  @@index([event_type, occurred_at])
  @@index([analytic_profile_id, occurred_at])
}

/// Aggregated entity representing a tracked analytic profile (see 06_ai_shopmall_ai_and_analytics_platform.md). 
/// Implements per-user, per-device, or per-actor analytic tracking profile. 3NF-compliant: ONE profile per entity/actor/session only; links canonical identifier to event records for attribution and analytics.
/// Business purpose: Normalized index for aggregating events, recommendations, and insights by user, device, or session. No pre-computed aggregations. Example: ID linking customer 313’s browser profile, their relevant events, and analytics. Used as the anchor for event attribution and personalization learning.
///
/// Key relationships: Linked to many analytic_events, recommendations, logs, and may reference actor (customer/seller/admin) tables.
/// Special behaviors: Profile created once; never duplicated. Source-level uniqueness enforced.
///
/// @namespace AnalyticsAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_analytic_profiles {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique analytic profile ID, unique across all events/links.
  id String @id @db.Uuid

  /// Optional – the actor’s ID (customer, seller, admin) this profile is tied to. References the relevant actor/user table, 3NF enforced. Null for anonymous/guest browsing sessions only.
  actor_id String? @db.Uuid

  /// Type of analytic profile (e.g., user, device, session, guest). Used for separating profiles in personalization use cases. Single atomic value only.
  profile_type String

  /// Unique key for this analytic entity (e.g., browser fingerprint, account UUID, device ID, session token). Uniqueness enforced at model level. Used for linking disparate events into same profile.
  profile_key String

  /// Timestamp profile was first initialized. Required; not an aggregate.
  first_seen_at DateTime @db.Timestamptz

  /// Timestamp of most recent associated analytic activity. Required; supports profile lifecycle management.
  ///
  last_seen_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  actor ai_shopmall_customers? @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  ai_shopmall_ai_recommendations  ai_shopmall_ai_recommendations[]
  ai_shopmall_analytic_events     ai_shopmall_analytic_events[]
  ai_shopmall_recommendation_logs ai_shopmall_recommendation_logs[]
  ai_shopmall_ai_alerts           ai_shopmall_ai_alerts[]

  @@unique([profile_type, profile_key])
  @@index([actor_id])
  @@index([last_seen_at])
}

/// Audit log for record of AI recommendation delivery and click/interaction results. Implements analytics requirements from 06_ai_shopmall_ai_and_analytics_platform.md for closed-loop recommendation feedback.
///
/// Business purpose: Records the actual delivery and interaction status of recommendations to users – for model/algorithm evaluation and A/B testing. 3NF: Each record is an atomic log. Example: Deliver 'product 1001' to visitor 311 at 2025-07-22T14:00Z, logged as displayed and later clicked.
///
/// Key relationships: Links to recommendation result (ai_shopmall_ai_recommendations) and analytic_profile (user/session/device identity). Never includes rollup or aggregation data. For reporting only, summary calculations must be in materialized views (mv_*).
///
/// @namespace AnalyticsAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_recommendation_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique for each recommendation log entry.
  id String @id @db.Uuid

  /// AI recommendation entry’s {@link ai_shopmall_ai_recommendations.id}. Links delivery to computed recommendation entry. Always required for normalization.
  recommendation_id String @db.Uuid

  /// Identity of the user/session/device for whom log is written. {@link ai_shopmall_analytic_profiles.id}. Required for normalization; 1:N from profile to logs.
  analytic_profile_id String @db.Uuid

  /// Medium/channel recommendation was delivered via (web, push, email, api call). Atomic only. Example: 'web', 'email'.
  delivery_channel String

  /// UTC timestamp recommendation was delivered or shown. Required; always atomic.
  delivered_at DateTime @db.Timestamptz

  /// Atomic status of recommendation outcome: 'displayed', 'clicked', 'ignored', 'converted'. No summaries or aggregate; one per row.
  interaction_status String

  /// UTC timestamp of relevant user interaction (‘clicked’, ‘converted’ etc) if occurred; null if not engaged. Maintains normalization.
  interaction_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  recommendation   ai_shopmall_ai_recommendations @relation(fields: [recommendation_id], references: [id], onDelete: Cascade)
  analytic_profile ai_shopmall_analytic_profiles  @relation(fields: [analytic_profile_id], references: [id], onDelete: Cascade)

  @@unique([recommendation_id, delivery_channel, delivered_at])
  @@index([analytic_profile_id, delivered_at])
}

/// AI-generated alerts for fraud or analytics anomalies (see 06_ai_shopmall_ai_and_analytics_platform.md). Implements requirements for alerting on detected business/ops anomalies.
///
/// Business purpose: Stores atomic, event-level alert records issued by analytics/fraud/AI layers. No pre-calculated counts by type or user. Example: 'multiple failed logins detected for user 88' or 'payment anomaly on order 1010'. Each row is a single alert occurrence.
///
/// Key relationships: Links to analytic_event, analytic_profile, possibly user (actors). Used for alert dashboards, push notifications, compliance audit. Alerts are never denormalized summaries.
///
/// @namespace AnalyticsAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_ai_alerts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique to this alert instance.
  id String @id @db.Uuid

  /// Identity profile linked to this alert entry. {@link ai_shopmall_analytic_profiles.id}.
  analytic_profile_id String @db.Uuid

  /// Analytic event that triggered this alert. {@link ai_shopmall_analytic_events.id}.
  analytic_event_id String @db.Uuid

  /// AI/analytic classification of alert (e.g., fraud_suspected, anomaly_detected, policy_violation). Atomic single value only. Never aggregate/rollup.
  alert_type String

  /// Short human-readable message explaining the alert or issue for dashboards or notifications. Single, atomic, fully normalized.
  alert_message String

  /// Integer representing alert severity, e.g., 1=info, 2=warning, 3=critical. Fully normalized; do not aggregate by type. Example: '3' for fraudulent payment detected.
  severity Int @db.Integer

  /// UTC datetime alert was emitted. Required per row; not a summary.
  alerted_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  analytic_profile ai_shopmall_analytic_profiles @relation(fields: [analytic_profile_id], references: [id], onDelete: Cascade)
  analytic_event   ai_shopmall_analytic_events   @relation(fields: [analytic_event_id], references: [id], onDelete: Cascade)

  @@unique([analytic_profile_id, alert_type, alerted_at])
  @@index([analytic_event_id])
  @@index([alert_type, alerted_at])
}

/// AI/analytics-driven segment definitions for the platform – see 06_ai_shopmall_ai_and_analytics_platform.md. Implements user/actor/behavior-based segment records. Each segment defines a rule or cohort for audience analysis and personalized actions.
///
/// Business purpose: Defines atomic segments (e.g., "high value buyers", "new users", "churn risk"). Used for targeting by personalization engines and analytics reporting. Maintains 3NF: Each segment row describes a segment with no membership/aggregation data.
///
/// Key relationships: Segments can be referenced by other analytics or personalization logic as needed. (User/actor-segment M:N membership should be tracked via a separate table if required.)
/// Special behaviors: Segment rules/queries stored as code or config, not pre-calculated groups. Naming uniqueness enforced per segment.
///
/// @namespace AnalyticsAI
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_segmentations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique per segment/campaign/audience definition.
  id String @id @db.Uuid

  /// Unique code identifier for the segment (e.g., 'HIGH_VALUE_BUYERS', 'ABANDONED_CART'). Atomic, 3NF enforced by unique constraint.
  segment_code String

  /// Human-friendly segment label. Example: 'High Value Buyers'. Never calculative/aggregated.
  segment_name String

  /// Rule, SQL, or code snippet that defines the segment logic (e.g., JSON, mini-language). Single value only.
  definition String

  /// UTC timestamp of segment definition creation. Audit-only; not an aggregated count.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([segment_code])
  @@index([created_at])
  @@index([segment_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-07-content_review_engagement.pris:
/// Product review details - Implements the product review requirements from the Content Review & Engagement document.
///
/// Captures customer-submitted product reviews, including star rating, textual feedback, media references, and associated metadata. Fully normalized 3NF structure (all business fields atomic, no redundancies). Example: A customer leaves a review after a successful purchase.
///
/// Key relationships: references products via product_id (from already existing Products component), associates to the review writer (customer_id), links to review reports, likes, and engagement logs.
/// Special behaviors: Only 1 review per customer per product enforced by unique index. Review cannot exist for unpurchased products, enforced at business logic level.
///
/// @namespace ContentReviewEngagement
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_reviews {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_shopmall_customers.id}
  customer_id String @db.Uuid

  /// Reviewed product's {@link ai_shopmall_products.id}
  product_id String @db.Uuid

  /// Review title - Implements review summary. Brief descriptive heading for the review. Ensures normalization; not duplicated elsewhere. Example: "Fantastic, fast delivery!"
  title String

  /// Review body content - Implements reviewer-provided textual feedback. Full review in natural language. Complies with 3NF by storing as atomic value. Example: "Arrived in two days and worked well..."
  body String

  /// Star rating value (e.g., 1-5) - Implements rating aspect of review. Integer representing the customer's evaluation. Ensures normalization, atomic value. Example: 4.
  rating_value Int @db.Integer

  /// Media attachment URI (optional) - Implements optional media evidence in review. URL to review photo/video. Null if no attachment. Supports normalization. Example: link to image.
  media_url String? @db.VarChar(80000)

  /// Creation timestamp - When the review was submitted. Ensures accurate event tracing and normalization. Example: 2025-07-22T12:20:00Z.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp - Reflects last review edit. Ensures auditability. Example: 2025-07-22T12:25:00Z.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_reviews_customer ai_shopmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  fk_reviews_product  ai_shopmall_products  @relation(fields: [product_id], references: [id], onDelete: Cascade)

  ai_shopmall_review_likes   ai_shopmall_review_likes[]
  ai_shopmall_review_reports ai_shopmall_review_reports[]

  @@unique([customer_id, product_id])
  @@index([product_id])
  @@index([customer_id])
  @@index([created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Review likes - Implements the 'like' system for reviews as required in the Content Review & Engagement module.
/// Represents a customer 'liking' (marking as helpful) a specific review. Enforces single like per customer-review. Maintains 3NF with all atomic fields. Example: Customer likes a review found useful.
///
/// Key relationships: References review (review_id), referencing customer (customer_id); no denormalized aggregates.
/// Special behaviors: Unique index to ensure one like per customer per review.
///
/// @namespace ContentReviewEngagement
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_review_likes {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target review's {@link ai_shopmall_reviews.id}
  review_id String @db.Uuid

  /// Liker customer {@link ai_shopmall_customers.id}
  customer_id String @db.Uuid

  /// Timestamp of like event - Records when like was registered. Ensures audit trail, normalization. Example: 2025-07-22T13:00:00Z.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_review_likes_review   ai_shopmall_reviews   @relation(fields: [review_id], references: [id], onDelete: Cascade)
  fk_review_likes_customer ai_shopmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  @@unique([review_id, customer_id])
  @@index([customer_id])
  @@index([review_id])
}

/// Review reporting - Fulfills the report/flagging requirement for moderation in the Content Review & Engagement system.
///
/// Represents a user-generated report (flag) on a review, citing violations or problematic content. Enforces 3NF with atomic fields. Example: Customer flags review as offensive.
///
/// Key relationships: References review (review_id), reporter (customer_id), links to moderation actions.
/// Special behaviors: Unique per reviewer per review.
///
/// @namespace ContentReviewEngagement
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_review_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Flagged review's {@link ai_shopmall_reviews.id}
  review_id String @db.Uuid

  /// Reporter customer's {@link ai_shopmall_customers.id}
  customer_id String @db.Uuid

  /// Reason for reporting (violation category or free text) - Implements user-provided rationale for reporting. Atomic string, e.g., 'Abuse', 'Spam'.
  reason String

  /// Optional extended report explanation - Free text. Allows more detail if needed. Normalized. Null if none.
  description String?

  /// Report created timestamp. For audit and history.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_review_reports_review   ai_shopmall_reviews   @relation(fields: [review_id], references: [id], onDelete: Cascade)
  fk_review_reports_customer ai_shopmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  ai_shopmall_moderation_actions ai_shopmall_moderation_actions[]

  @@unique([review_id, customer_id])
  @@index([customer_id])
  @@index([created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Standalone rating entity - Implements the requirement for storing granular per-entity ratings, decoupled from review text (some flows prefer rating only).
///
/// Records a rating value customers give to a product, possibly without textual review. Maintains normalization. Example: Customer gives 5 stars without comment.
///
/// Key relationships: product_id, customer_id (from existing tables), can be nullable if only review is present.
/// Special behaviors: Ensures a customer may rate only once per product (unique index).
///
/// @namespace ContentReviewEngagement
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_ratings {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer giving rating {@link ai_shopmall_customers.id}
  customer_id String @db.Uuid

  /// Rated product's {@link ai_shopmall_products.id}
  product_id String @db.Uuid

  /// Numeric rating value (e.g., 1-5) - Implements atomic score. Normalized. Example: 5.
  rating_value Int @db.Integer

  /// When the rating was made. For event tracing.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_ratings_customer ai_shopmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  fk_ratings_product  ai_shopmall_products  @relation(fields: [product_id], references: [id], onDelete: Cascade)

  @@unique([customer_id, product_id])
  @@index([product_id])
}

/// Q&A questions - Implements the question-asking feature from the Content Review & Engagement document.
///
/// Represents a customer's product, order, or general question for sellers/admins (pre-/post-purchase). Maintains normalized 3NF structure. Example: 'How long is the warranty?'
///
/// Key relationships: Linked to customer (asker), product being asked about, and answer entity. May be associated to order for post-sale.
/// Special behaviors: One question can exist per customer per product per subject (business logic).
///
/// @namespace ContentReviewEngagement
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_questions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Asking customer's {@link ai_shopmall_customers.id}
  customer_id String @db.Uuid

  /// Subject product's {@link ai_shopmall_products.id}
  product_id String? @db.Uuid

  /// Question title. Fulfills inquiry summary requirement. Atomic string. Example: 'Return policy?'.
  title String

  /// Full question details. Implements main inquiry content. Example: 'Can I return after 14 days?'
  body String

  /// Question submission date/time.
  created_at DateTime @db.Timestamptz

  /// Whether the question has been answered (resolved). Maintains normalized status flag. Example: false initially, true after answer posted.
  resolved Boolean

  //----
  // RELATIONS
  //----
  fk_questions_customer ai_shopmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  fk_questions_product  ai_shopmall_products? @relation(fields: [product_id], references: [id], onDelete: Cascade)

  ai_shopmall_answers ai_shopmall_answers[]

  @@index([customer_id])
  @@index([product_id])
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Q&A answers - Implements the question answering requirement in the Content Review & Engagement doc.
///
/// Stores seller/admin answers to customer questions. Maintains referential link to question and responder. Normalized (one answer per question, all data atomic). Example: Seller responds to return policy Q.
///
/// Key relationships: question_id to ai_shopmall_questions, responder_id links to actors.
/// Special behaviors: Enforces one answer per question per responder. 
///
/// @namespace ContentReviewEngagement
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_answers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent question's {@link ai_shopmall_questions.id}
  question_id String @db.Uuid

  /// Responder's actor ID (seller/admin) from related components. Distinction made in business logic.
  responder_id String @db.Uuid

  /// Answer content - Full text of answer. Normalized field. Example: 'Returns accepted within 30 days.'
  body String

  /// Timestamp of answer post.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_answers_question  ai_shopmall_questions @relation(fields: [question_id], references: [id], onDelete: Cascade)
  fk_answers_responder ai_shopmall_sellers   @relation(fields: [responder_id], references: [id], onDelete: Cascade)

  @@unique([question_id, responder_id])
  @@index([responder_id])
  @@index([created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// General-purpose comment entity - Implements the comment feature for reviews, bulletins, and Q&A, following Content Review & Engagement requirements.
///
/// Atomic unit for user-generated comments against diverse parent entities (referenced via parent_type+parent_id pattern in application logic). Normalized; all fields atomic. Example: Comment posted under a bulletin or a review.
///
/// Key relationships: links to commenter (customer/admin), stores parent type/id for business-layer linking.
/// Special behaviors: parent_type & parent_id together define the comment target (polymorphic at business level).
///
/// @namespace ContentReviewEngagement
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Comment author's ID (customer/admin).
  commenter_id String @db.Uuid

  /// ID of the parent entity (review, bulletin, question, answer). Implements polymorphic relationship at business logic layer. Not FK-enforced in DB. Example: points to ai_shopmall_reviews.id or ai_shopmall_bulletins.id etc.
  parent_id String @db.Uuid

  /// Type of parent entity (e.g., 'review', 'bulletin', 'question', 'answer'). Implements polymorphic relationship handling at business logic level. Normalized: no denormalization of target entity.
  parent_type String

  /// Comment content - Implements user comment. Normalized string. Example: 'Thanks for the info!'
  body String

  /// Comment submission timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_comments_commenter ai_shopmall_customers @relation(fields: [commenter_id], references: [id], onDelete: Cascade)

  @@index([commenter_id])
  @@index([parent_id])
  @@index([parent_type])
  @@index([created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Bulletin entity - Implements platform/community/FAQ bulletin posts as required in Content Review & Engagement.
///
/// Represents system, admin, or announcement posts that users can read or comment on. Normalized, all fields atomic. Example: 'System Maintenance on 7/1.'
///
/// Key relationships: Author (admin_id), category (category_id), comments via ai_shopmall_comments.
/// Special behaviors: Enforces category linkage and admin authorship.
///
/// @namespace ContentReviewEngagement
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_bulletins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Category for the bulletin post {@link ai_shopmall_bulletin_categories.id}
  category_id String @db.Uuid

  /// Admin author {@link ai_shopmall_administrators.id}
  admin_id String @db.Uuid

  /// Bulletin post title - headline. Normalized. Example: 'Important Policy Update'.
  title String

  /// Bulletin post main content. Normalized. Example: Details of the announcement.
  body String

  /// Whether bulletin is pinned (shown at top). Fulfills admin pinning requirement. Example: true for urgent/FAQ posts.
  pinned Boolean

  /// Post creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update to bulletin. Allows audit/change tracking.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_bulletins_category ai_shopmall_bulletin_categories @relation(fields: [category_id], references: [id], onDelete: Cascade)
  fk_bulletins_admin    ai_shopmall_administrators      @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  @@index([category_id])
  @@index([admin_id])
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Bulletin category - Implements category structure for bulletin posts as specified in Content Review & Engagement doc.
///
/// Represents FAQ, system, announcement, or community topic category. Normalized, atomic fields only. Example: 'Announcements', 'Policies'.
///
/// Key relationships: Links to bulletins via category_id.
/// Special behaviors: Category names unique.
///
/// @namespace ContentReviewEngagement
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_bulletin_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Category name. Implements unique label. Atomic, not duplicated. Example: 'FAQ', 'Maintenance'.
  name String

  /// Category creation date.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shopmall_bulletins ai_shopmall_bulletins[]

  @@unique([name])
}

/// Engagement log - Implements the audit trail and engagement tracking for content interactions.
///
/// Stores action logs (view, like, reply, report) for reviews, questions, bulletins, etc. Ensures normalized structure. Example: Customer views review, logs 'view' event.
///
/// Key relationships: actor_id (any user), target_entity_id + target_entity_type for polymorphic target.
/// Special behaviors: Used for analytics and monitoring engagement rates.
///
/// @namespace ContentReviewEngagement
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_engagement_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Actor performing engagement (customer or admin or seller, depending on target).
  actor_id String @db.Uuid

  /// ID of engaged entity (review, question, etc.). Implements polymorphic reference by business logic.
  target_entity_id String @db.Uuid

  /// Type of engaged entity (e.g., 'review', 'bulletin', 'question', etc.). Normalized for analytics/use-cases.
  target_entity_type String

  /// Type of engagement (e.g., 'view', 'like', 'reply', 'report'). Atomic, used for analytics.
  action_type String

  /// Timestamp of engagement event.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_engagement_logs_actor ai_shopmall_customers @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  @@index([actor_id])
  @@index([target_entity_id])
  @@index([target_entity_type])
  @@index([created_at])
}

/// Moderation action - Implements moderation and compliance enforcement for community content as required in Content Review & Engagement.
///
/// Represents actions taken by admins or automated AI (delete, block, edit, allow). Normalized, all fields atomic. Example: Admin flags review as abuse, action logged here.
///
/// Key relationships: moderator_id (admin or automated), target_entity_id/type (polymorphic), links to reports.
/// Special behaviors: Stores action type, reason, and reference to original report_id if applicable.
///
/// @namespace ContentReviewEngagement
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_moderation_actions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Moderator actor id (admin or AI bot, references already existing actors or systemic users).
  moderator_id String @db.Uuid

  /// Original report that prompted moderation ({@link ai_shopmall_review_reports.id}), if applicable. Nullable as not all actions arise from user reports.
  report_id String? @db.Uuid

  /// ID of moderated entity (polymorphic, e.g., review, comment, bulletin) - atomic field.
  target_entity_id String @db.Uuid

  /// Type/name of moderated entity (e.g., 'review', 'comment', 'bulletin'). Normalized.
  target_entity_type String

  /// Action performed by moderator (e.g., 'delete', 'block', 'approve', 'edit'). Atomic, for audit/export/reporting.
  action_type String

  /// Rationale for moderation action. Explains why content was moderated. Atomic. Example: 'Hate speech violation'.
  reason String?

  /// Date/time when moderation action was applied.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_moderation_actions_moderator ai_shopmall_administrators  @relation(fields: [moderator_id], references: [id], onDelete: Cascade)
  fk_moderation_actions_report    ai_shopmall_review_reports? @relation(fields: [report_id], references: [id], onDelete: Cascade)

  @@index([moderator_id])
  @@index([report_id])
  @@index([target_entity_id])
  @@index([target_entity_type])
  @@index([created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-08-favorites_personalization.pris:
/// Favorite Entity Mapping Table – Implements multi-entity favorites as required in Favorites & Personalization. Maps each user's favorite items (product, seller, address, inquiry) to their folders with tags and creation audit. Maintains 3NF by referencing all related entities via FKs and storing only atomic relationships, not denormalized info.
///
/// @namespace FavoritesPersonalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_favorites {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each favorite mapping record.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_shopmall_customers.id}. Links favorite to actual user (customer).
  customer_id String @db.Uuid

  /// Folder's {@link ai_shopmall_favorite_folders.id}. Classifies the favorite entry for organization/grouping.
  favorite_folder_id String @db.Uuid

  /// Type of entity being favorited (e.g., product, seller, address, inquiry). Implements multi-entity flexibility per requirements. Normalized as atomic value.
  entity_type String

  /// ID of the favorited entity. This flexibly refers to the entity corresponding to entity_type. Fully normalized as reference only. Example: For product favorite, stores product UUID.
  entity_id String @db.Uuid

  /// Timestamp when the favorite was added. Enables audit and last-access logic as required. Maintains normalization; example: '2025-07-21T13:22:00Z'.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_favorites_customers        ai_shopmall_customers        @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  fk_favorites_favorite_folders ai_shopmall_favorite_folders @relation(fields: [favorite_folder_id], references: [id], onDelete: Cascade)

  ai_shopmall_favorite_tags ai_shopmall_favorite_tags[]

  @@unique([customer_id, entity_type, entity_id, favorite_folder_id])
  @@index([favorite_folder_id, created_at])
  @@index([entity_type(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Favorite Folder Table – Implements requirement for organizing favorites into folders (custom and default) per customer. Lets users create/delete/rename folders for grouping favorites. 3NF: Folder holds only folder attributes and user reference, not favorite data.
///
/// @namespace FavoritesPersonalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_favorite_folders {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each favorite folder.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_shopmall_customers.id}. Links folder to the owning user.
  customer_id String @db.Uuid

  /// Folder name. User-created identifier for organizing favorites. Ensures normalization by only storing atomic label. Example: 'Wishlist', 'Work Supplies'.
  name String

  /// Indicates if this is the system default folder (true) or a user-created folder (false). Implements business needs for required default folders.
  is_default Boolean

  /// Timestamp the folder was created. For audit trail and recovery.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_favorite_folders_customers ai_shopmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  ai_shopmall_favorites ai_shopmall_favorites[]

  @@unique([customer_id, name])
  @@index([customer_id])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Favorite Tag Table – Implements tagging requirements for flexible searching/categorizing of favorites. Each tag is attached to a single favorite and exists as a separate row (3NF). Prevents duplicate tags per favorite.
///
/// @namespace FavoritesPersonalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_favorite_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each tag record.
  id String @id @db.Uuid

  /// Favorite's {@link ai_shopmall_favorites.id}. Links tag to favorited item.
  favorite_id String @db.Uuid

  /// Tag value. Short label for categorization/filtering favorites. Fully normalized as atomic string. Example: 'gift', 'eco'.
  tag String

  //----
  // RELATIONS
  //----
  fk_favorite_tags_favorites ai_shopmall_favorites @relation(fields: [favorite_id], references: [id], onDelete: Cascade)

  @@unique([favorite_id, tag])
  @@index([tag(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Notification Preferences Table – Implements user-personalized notification settings for favorites/folders. Stores which notification types are enabled/disabled for a favorite or folder; distinguished by target_type. 3NF is maintained by separating notification config from favorites/folder data and indexing by both target_type/target_id and customer.
///
/// @namespace FavoritesPersonalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_notification_preferences {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each notification preference record.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_shopmall_customers.id}. Owner of this notification preference.
  customer_id String @db.Uuid

  /// Scope: 'favorite' or 'folder'. Implements requirement for preference type distinction. Example: 'favorite'.
  target_type String

  /// Target favorite/folder the preference is for. Ensures referential clarity. For folder scope, stores folder UUID.
  target_id String @db.Uuid

  /// Comma- or pipe-separated notification types enabled for this object. Implements requirements supporting multi-type (push,email,SMS): e.g., 'push,email'.
  notif_types_enabled String

  //----
  // RELATIONS
  //----
  fk_notification_preferences_customers ai_shopmall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  @@unique([customer_id, target_type, target_id])
  @@index([notif_types_enabled(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-09-security_compliance.prisma:
/// Permission Role Entity - Implements core RBAC security requirements; separates roles from permissions and user assignments, ensuring 3NF and auditable role management.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_permission_roles {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each permission role record.
  id String @id @db.Uuid

  /// Role code - unique, short, for RBAC and API lookups.
  code String

  /// Human-readable name for admin/UI context.
  name String

  /// Role business description, optional for audit.
  description String?

  /// Role creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Role update/change timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_shopmall_role_permissions ai_shopmall_role_permissions[]
  ai_shopmall_user_permissions ai_shopmall_user_permissions[]
  ai_shopmall_access_logs      ai_shopmall_access_logs[]
  ai_shopmall_security_events  ai_shopmall_security_events[]

  @@unique([code])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Links permission roles to permission codes (action/resource statements) for RBAC enforcement; each (role, permission_code) pair is unique.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_role_permissions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for a role-permission mapping.
  id String @id @db.Uuid

  /// Reference to role's ai_shopmall_permission_roles.id.
  permission_role_id String @db.Uuid

  /// Permission code (static from codebase/config, e.g. 'VIEW_ORDER'). Stored here for mapping; not a foreign key.
  permission_code String

  /// Assignment creation timestamp for audit trail.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  permission_role ai_shopmall_permission_roles @relation(fields: [permission_role_id], references: [id], onDelete: Cascade)

  @@unique([permission_role_id, permission_code])
  @@index([created_at])
}

/// Assigns roles to users—atomic user-role mapping for RBAC, supporting multi-role and audit logs; (user_id, permission_role_id) unique.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_user_permissions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for user-role assignment.
  id String @id @db.Uuid

  /// User ID from actors domain models (referencing users, sellers, admins, decoupled for cross-domain linking).
  user_id String @db.Uuid

  /// Assigned role reference to ai_shopmall_permission_roles.id.
  permission_role_id String @db.Uuid

  /// Timestamp of role assignment to user, for audit compliance.
  assigned_at DateTime @db.Timestamptz

  /// Timestamp if/when assignment is revoked. Null if currently active.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user            ai_shopmall_customers        @relation(fields: [user_id], references: [id], onDelete: Cascade)
  permission_role ai_shopmall_permission_roles @relation(fields: [permission_role_id], references: [id], onDelete: Cascade)

  @@unique([user_id, permission_role_id])
  @@index([permission_role_id])
  @@index([assigned_at])
}

/// Tracks all user access/auth events for auditing and compliance; event type, user, role involved, source channel, and IP/device are atomic; append-only.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_access_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for an access log entry.
  id String @id @db.Uuid

  /// User ID (cross-domain ref), performing the access event. Nullable for guest/system access.
  user_id String @db.Uuid

  /// Role context (if any) referencing ai_shopmall_permission_roles.id in this event.
  permission_role_id String? @db.Uuid

  /// Access event type ('LOGIN','ROLE_ASSIGN','PERMISSION_CHECK','LOGOUT','TOKEN_REFRESH','FAILED_AUTH') etc.
  event_type String

  /// Channel of access ('WEB','API','MOBILE','ADMIN').
  event_source String

  /// IPv4/IPv6 address as string for forensics/audit.
  ip_address String

  /// HTTP user agent/device string. Optional context.
  user_agent String?

  /// Exact event timestamp for audit/fraud tracing.
  occurred_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user            ai_shopmall_customers         @relation(fields: [user_id], references: [id], onDelete: Cascade)
  permission_role ai_shopmall_permission_roles? @relation(fields: [permission_role_id], references: [id], onDelete: Cascade)

  @@index([permission_role_id])
  @@index([user_id, occurred_at])
  @@index([event_type])
}

/// Logs security incidents/alerts (failed logins, privilege, fraud signs); all atomic details for post-incident audit; append-only; user/role refs are nullable for system-wide events.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_security_events {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for security event.
  id String @id @db.Uuid

  /// User involved (if any); cross-domain; can be null for anonymous/system/global.
  user_id String? @db.Uuid

  /// Role involved (if any), referencing ai_shopmall_permission_roles.id.
  permission_role_id String? @db.Uuid

  /// Security incident type: e.g., 'FAILED_LOGIN', 'PRIV_ESCALATION', 'FRAUD_FLAG', etc.
  event_type String

  /// Structured incident metadata or free-text details for compliance and forensics.
  event_details String?

  /// Timestamp of event creation for timeline analysis.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user            ai_shopmall_customers?        @relation(fields: [user_id], references: [id], onDelete: Cascade)
  permission_role ai_shopmall_permission_roles? @relation(fields: [permission_role_id], references: [id], onDelete: Cascade)

  @@index([user_id])
  @@index([permission_role_id])
  @@index([event_type, created_at])
}

/// Tracks which user accepted/revoked which policy for compliance (GDPR/CCPA), unique per (user, policy_code) until revoked; append-only for audit.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_policy_acceptances {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for policy acceptance.
  id String @id @db.Uuid

  /// User who accepted/revoked the policy (ref to actors domain).
  user_id String @db.Uuid

  /// Policy code for joined requirement, e.g. 'PRIVACY','TOS','MARKETING_CONSENT'.
  policy_code String

  /// Whether accepted (true) or declined/revoked (false).
  accepted Boolean

  /// Action timestamp for acknowledgment or revocation.
  accepted_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user ai_shopmall_customers @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@unique([user_id, policy_code])
  @@index([accepted_at])
}

/// Records all data retention/deletion/anonymization events for regulatory compliance (GDPR, CCPA); atomic details; append-only; may include user reference or global/system context.
///
/// @namespace SecurityCompliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_shopmall_data_retention_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for retention/deletion log.
  id String @id @db.Uuid

  /// Subject user (if any); cross-domain; nullable for system/global retentions.
  user_id String? @db.Uuid

  /// Retention event type (e.g. 'RETENTION_CHECK','ANONYMIZATION','DATA_DELETION').
  event_type String

  /// Type/category of data affected (e.g. 'ORDER','PROFILE','SESSION').
  data_type String

  /// Extra details about event (e.g. what data, anonymization method, job id); atomic per event.
  event_details String?

  /// Event timestamp for compliance/audit compliance.
  occurred_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user ai_shopmall_customers? @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@index([user_id])
  @@index([event_type, occurred_at])
}

