import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { aiShopmallPluginModule } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopmallPluginModule";
import type { aiShopmallPagePluginModule } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopmallPagePluginModule";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 다양한 검색 필터, 페이지네이션, 정렬, 권한 검사로 플러그인 모듈 목록 조회 기능을 검증합니다.
 *
 * - 여러 code, name, version 조합으로 플러그인 모듈 4개 등록
 * - code, name, version 검색 필터, 페이징, 정렬, 메타 정보 필드 검증
 * - 전체목록·빈조회(조건미일치)·과도한 page/limit·잘못된 order 등 엣지케이스 확인
 * - 미인증 접근/권한오류 동작까지 폭넓게 점검
 *
 * 시나리오 단계
 * 1. Plugin module 4가지 고유 조합으로 등록 (distinct code/name/version)
 * 2. code, name, version 각 검색 쿼리(정확/부분일치)로 필터 결과 검증
 * 3. 페이지네이션/정렬 옵션으로 리스트 페이징·순서 정확성·메타정보 확인
 * 4. 전체 목록 호출, 빈 결과, 과도한 페이지/limit 요청 등 엣지케이스 체크
 * 5. 잘못된 order 값·비로그인 접속 등 오류 응답 동작 검증
 */
export async function test_api_aiShopmall_test_list_plugin_modules_with_various_search_filters(
  connection: api.IConnection,
) {
  // 1. test data: 코드/이름/버전 다르게 4개 플러그인 등록
  const testSpecs = [
    { code: 'alpha', name: 'Alpha Module', version: '1.0.0' },
    { code: 'bravo', name: 'Bravo Extension', version: '1.1.0' },
    { code: 'charlie', name: 'Charlie Plug', version: '2.0.1' },
    { code: 'delta', name: 'Delta Tool', version: '2.0.1' },
  ];
  for (const spec of testSpecs) {
    const created = await api.functional.aiShopmall.pluginModules.post(connection, {
      body: {
        code: spec.code,
        name: spec.name,
        version: spec.version,
        settings_schema: '{"type":"object"}',
        description: spec.name + ' description',
      } satisfies aiShopmallPluginModule.ICreate,
    });
    typia.assert(created);
  }
  // 2. code 일부 일치(query)
  let result = await api.functional.aiShopmall.pluginModules.patch(connection, {
    body: { query: 'alp' },
  });
  typia.assert(result);
  TestValidator.predicate('code partial match')(result.data.some(mod => mod.code === 'alpha'));
  // 2-2. 이름 검색
  result = await api.functional.aiShopmall.pluginModules.patch(connection, {
    body: { query: 'Charlie' },
  });
  typia.assert(result);
  TestValidator.equals('search by name')(result.data[0].name)('Charlie Plug');
  // 2-3. 버전 검색
  result = await api.functional.aiShopmall.pluginModules.patch(connection, {
    body: { query: '1.0.0' },
  });
  typia.assert(result);
  TestValidator.equals('search by version')(result.data[0].version)('1.0.0');
  // 3. 페이지네이션 정렬 옵션
  result = await api.functional.aiShopmall.pluginModules.patch(connection, {
    body: { page: 1, limit: 2, order_by: 'name', order: 'desc' },
  });
  typia.assert(result);
  TestValidator.equals('pagination limit')(result.pagination.limit)(2);
  TestValidator.equals('order desc')(result.data[0].name > result.data[1].name)(true);
  // 4. 메타정보 필드 확인
