 *
 * 입력이 모두 누락된 빈 body는 스키마상 허용이므로(모든 필드가 optional), 에러케이스에서 제외합니다.
 * 각 error 검증 시 TestValidator.error를 활용해 실제 런타임 오류 발생 여부만 체크하며, 에러 메시지 등은 따로 확인하지 않습니다.
 *
 * [검증 단계]
 * 1. page: 음수 입력 오류
 * 2. page: 비정수 입력 오류
 * 3. limit: 음수 입력 오류
 * 4. limit: 0 입력 오류
 * 5. order: 허용 enum 외 값 입력 오류
 * 6. 추가 속성(foo 등) 입력 시 오류
 */
export async function test_api_aiShopmall_test_list_plugin_modules_with_invalid_request_body(
  connection: api.IConnection,
) {
  // 1. page: 음수 입력 오류
  await TestValidator.error("negative page must fail")(async () => {
    await api.functional.aiShopmall.pluginModules.patch(connection, {
      body: {
        page: -1 as number & tags.Type<"int32">,
      },
    });
  });

  // 2. page: 비정수 입력 오류
  await TestValidator.error("non-integer page must fail")(async () => {
    await api.functional.aiShopmall.pluginModules.patch(connection, {
      body: {
        page: 1.5 as unknown as number & tags.Type<"int32">,
      },
    });
  });

  // 3. limit: 음수 입력 오류
  await TestValidator.error("negative limit must fail")(async () => {
    await api.functional.aiShopmall.pluginModules.patch(connection, {
      body: {
        limit: -10 as number & tags.Type<"int32">,
      },
    });
  });

  // 4. limit: 0 입력 오류
  await TestValidator.error("zero limit must fail")(async () => {
    await api.functional.aiShopmall.pluginModules.patch(connection, {
      body: {
        limit: 0 as number & tags.Type<"int32">,
      },
    });
  });

  // 5. order: 허용 enum 외 값 입력 오류
  await TestValidator.error("invalid order value must fail")(async () => {
    await api.functional.aiShopmall.pluginModules.patch(connection, {
      body: {
        order: "ascending" as "asc" | "desc",
      },
    });
  });

  // 6. 임의/추가 속성 포함 시 오류
  await TestValidator.error("unexpected property must fail")(async () => {
    await api.functional.aiShopmall.pluginModules.patch(connection, {
      body: {
        page: 1 as number & tags.Type<"int32">,
        foo: "bar" as unknown as never,
