import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { aiShopmallPluginModule } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopmallPluginModule";

/**
 * aiShopmall 플러그인 모듈 상세 조회 API 정상 동작 검증
 *
 * 신규 등록된 플러그인 모듈의 UUID로 상세 정보를 조회할 때,
 * 시스템이 올바른 메타데이터를 반환하며 권한/감사(내부 정책) 로직이 작동함을 확인한다.
 *
 * [프로세스]
 * 1. 신규 플러그인 모듈을 POST로 등록하여 유효 id 확보
 * 2. 확보한 id로 GET /aiShopmall/pluginModules/{id} 상세 조회
 * 3. 응답이 aiShopmallPluginModule 타입에 완전히 부합하며,
 *    주요 필드들이 등록값과 정확히 일치하는지 검증
 * 4. created_at, updated_at 등 시스템 자동할당 필드는 날짜 포맷 검증(실제 값은 서로 다를 수 있음)
 * 5. 권한/감사/로깅 등 내부 제약은 테스트 환경상 실제 검증 불가이므로 문서로만 언급
 */
export async function test_api_aiShopmall_pluginModules_getById(
  connection: api.IConnection,
) {
  // 1. 플러그인 모듈 신규 등록: POST로 유효 ID 확보
  const createInput: aiShopmallPluginModule.ICreate = {
    code: RandomGenerator.alphabets(8),
    name: `테스트모듈_${RandomGenerator.alphabets(4)}`,
    description: `e2e 자동화 테스트용 설명 - ${RandomGenerator.paragraph()()}`,
    version: "1.0.0",
    settings_schema: '{"type":"object","properties":{"foo":{"type":"string"}}}',
  };
  const created: aiShopmallPluginModule = await api.functional.aiShopmall.pluginModules.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. 확보한 id 기반으로 상세 정보 조회
  const detail: aiShopmallPluginModule = await api.functional.aiShopmall.pluginModules.getById(connection, {
    id: created.id,
  });
  typia.assert(detail);

  // 3. 주요 메타데이터 필드값이 등록 내용과 일치하는지 확인
  TestValidator.equals("id 일치")(detail.id)(created.id);
  TestValidator.equals("code 일치")(detail.code)(createInput.code);
  TestValidator.equals("name 일치")(detail.name)(createInput.name);
  TestValidator.equals("description 일치")(detail.description)(createInput.description);
  TestValidator.equals("version 일치")(detail.version)(createInput.version);
  TestValidator.equals("settings_schema 일치")(detail.settings_schema)(createInput.settings_schema);
  // 시스템 할당 날짜 필드는 타입·형식만 검증
  TestValidator.predicate("created_at은 ISO8601 날짜 문자열")(!!detail.created_at && !isNaN(Date.parse(detail.created_at)));
  TestValidator.predicate("updated_at은 ISO8601 날짜 문자열")(!!detail.updated_at && !isNaN(Date.parse(detail.updated_at)));
}

