 * [진행 절차]
 * 1. 테스트용 고유 code를 가진 플러그인 모듈을 정상적으로 등록합니다.
 * 2. 동일한 code로 또 다른 플러그인 모듈을 등록 시도합니다.
 * 3. 이때 409 conflict(고유성 위반) 오류가 발생하는지 확인합니다.
 */
export async function test_api_aiShopmall_test_register_plugin_module_with_duplicate_code(
  connection: api.IConnection,
) {
  // 1. 테스트용 고유 코드 및 플러그인 데이터 준비
