    body: pluginBody,
  });
  typia.assert(created);
  TestValidator.equals("plugin module code matches")(created.code)(duplicateCode);

  // 3. 동일한 code로 두 번째 플러그인 등록 시 conflict 오류를 기대함
  await TestValidator.error("duplicate code conflict 오류")(
    async () => {
      await api.functional.aiShopmall.pluginModules.post(connection, {
        body: {
          ...pluginBody,
          name: pluginBody.name + "-두번째시도",
        },
      });
    }
  );
}

