    async () => {
      await api.functional.aiShopmall.pluginModules.post(connection, {
        body: {
          code: "bad-module-3",
          name: "Invalid JSON Schema",
          version: "1.0.0",
          settings_schema: "123", // not a valid JSON schema
        },
      });
    },
  );
