 * 이 테스트는 다음을 검증합니다:
 * 1. 플러그인 모듈을 신규 등록 (POST)하여 유효한 id를 확보한다.
 * 2. 코드, 명칭, 설명, 버전, 설정 스키마 등 모든 변경 가능한 정보를 새로운 값으로 전체 업데이트한다.
 * 3. 응답이 정상적으로 변경 내용을 반영하는지(각 필드, updated_at 포함) 검증한다.
 * 4. description 필드만 단독 갱신하는 부분 업데이트를 수행, 나머지 값은 유지되는지 점검한다.
 * 5. 같은 description으로 반복 업데이트(아이덴포턴시) 시 값 변동이 없는지 검증한다.
 *
 * 각 단계별로 필드값 고유성, 응답 반영, 타임스탬프 변경 여부까지 검사하여
 * 플러그인 모듈 메타데이터 저장 및 부분/전체 수정, 아이덴포턴시를 종합적으로 보장합니다.
 */
export async function test_api_aiShopmall_test_update_plugin_module_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 신규 플러그인 모듈 생성 (POST)
  const createInput: aiShopmallPluginModule.ICreate = {
    code: `plugin_code_${RandomGenerator.alphabets(8)}`,
    name: `Plugin Name ${RandomGenerator.alphabets(5)}`,
    description: 'Initial description for E2E',
    version: '1.0.0',
    settings_schema: '{"type":"object","properties":{"enabled":{"type":"boolean"}}}',
  };
  const created = await api.functional.aiShopmall.pluginModules.post(connection, {
    body: createInput,
  });
  typia.assert(created);
  TestValidator.equals('created code')(created.code)(createInput.code);
  TestValidator.equals('created name')(created.name)(createInput.name);
  TestValidator.equals('created desc')(created.description)(createInput.description);
  TestValidator.equals('created version')(created.version)(createInput.version);
  TestValidator.equals('created schema')(created.settings_schema)(createInput.settings_schema);

  // 2. 전체 필드 업데이트(코드, 명칭, 설명, 버전, 스키마)
  const updateInput: aiShopmallPluginModule.IUpdate = {
    code: `plugin_code_${RandomGenerator.alphabets(8)}`,
    name: `Updated Name ${RandomGenerator.alphabets(6)}`,
    description: '업데이트를 통한 전체 변경',
    version: '2.0.0-beta',
    settings_schema: '{"type":"object","properties":{"enabled":{"type":"boolean"},"timeout":{"type":"number"}}}',
  };
  const updated = await api.functional.aiShopmall.pluginModules.putById(connection, {
    id: created.id,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals('update code')(updated.code)(updateInput.code);
  TestValidator.equals('update name')(updated.name)(updateInput.name);
  TestValidator.equals('update desc')(updated.description)(updateInput.description);
  TestValidator.equals('update version')(updated.version)(updateInput.version);
  TestValidator.equals('update schema')(updated.settings_schema)(updateInput.settings_schema);
  TestValidator.notEquals('updated_at changed')(updated.updated_at)(created.updated_at);

  // 3. 부분 업데이트: description만 변경, 나머지는 기존 값 유지
  const partialDesc = '설명만 부분 변경';
  const partialInput: aiShopmallPluginModule.IUpdate = { description: partialDesc };
  const partially = await api.functional.aiShopmall.pluginModules.putById(connection, {
    id: created.id,
    body: partialInput,
  });
  typia.assert(partially);
  TestValidator.equals('부분 code 유지')(partially.code)(updateInput.code);
  TestValidator.equals('부분 name 유지')(partially.name)(updateInput.name);
  TestValidator.equals('부분 description 변경')(partially.description)(partialDesc);
  TestValidator.equals('부분 version 유지')(partially.version)(updateInput.version);
  TestValidator.equals('부분 schema 유지')(partially.settings_schema)(updateInput.settings_schema);
  TestValidator.notEquals('updated_at 재변경')(partially.updated_at)(updated.updated_at);

  // 4. description 부분 업데이트 반복: idempotency 검증
  const repeated = await api.functional.aiShopmall.pluginModules.putById(connection, {
    id: created.id,
    body: partialInput,
  });
  typia.assert(repeated);
  TestValidator.equals('idempotent code')(repeated.code)(partially.code);
  TestValidator.equals('idempotent name')(repeated.name)(partially.name);
  TestValidator.equals('idempotent desc')(repeated.description)(partialDesc);
  TestValidator.equals('idempotent version')(repeated.version)(partially.version);
  TestValidator.equals('idempotent schema')(repeated.settings_schema)(partially.settings_schema);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
