import api from "@ORGANIZATION/PROJECT-api";
import type { aiShopmallPluginModule } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopmallPluginModule";

/**
 * Validate error handling for updating plugin module codes.
 *
 * This test ensures that updating a plugin module's code to one already used by another module results in a conflict, enforcing code uniqueness.
 *
 * Step-by-step process:
 * 1. Register plugin module A with a unique code.
 * 2. Register plugin module B with a different unique code.
 * 3. Attempt to update plugin module B's code to match module A's code.
 * 4. Assert a 409 conflict is triggered due to code uniqueness violation.
 */
export async function test_api_aiShopmall_pluginModules_test_update_plugin_module_with_duplicate_code(
  connection: api.IConnection,
) {
  // 1. Register plugin module A
  const codeA = RandomGenerator.alphaNumeric(8);
  const moduleA = await api.functional.aiShopmall.pluginModules.post(connection, {
    body: {
      code: codeA,
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(1),
      version: "1.0.0",
      settings_schema: '{}',
    } satisfies aiShopmallPluginModule.ICreate,
  });
  typia.assert(moduleA);

  // 2. Register plugin module B
  const codeB = RandomGenerator.alphaNumeric(8);
  const moduleB = await api.functional.aiShopmall.pluginModules.post(connection, {
    body: {
      code: codeB,
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(1),
      version: "1.0.0",
      settings_schema: '{}',
    } satisfies aiShopmallPluginModule.ICreate,
  });
  typia.assert(moduleB);

  // 3. Attempt to update module B's code to module A's code (should fail)
  await TestValidator.error("409 conflict on code duplication")(
    async () => {
      await api.functional.aiShopmall.pluginModules.putById(connection, {
        id: moduleB.id,
        body: {
          code: codeA,
        } satisfies aiShopmallPluginModule.IUpdate,
      });
    },
  );
}

