import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { aiShopmallPluginModule } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopmallPluginModule";

/**
 * 플러그인 모듈 업데이트 기능의 유효성 오류 검증
 *
 * 플러그인(확장 모듈) 정보를 잘못 입력(필수값 누락, 빈 문자열 입력, 잘못된 settings_schema 포맷 등)한 경우 시스템이
 * 적절한 400 Validation 에러를 반환하는지 검증합니다.
 *
 * 1. 정상 입력 데이터로 플러그인 모듈을 신규 등록하여 id 확보
 * 2. 정상 등록된 id에 대해 아래와 같은 다양한 잘못된 update 입력으로 400 에러 검증
 *    - 필수 필드에 빈 문자열(code, name, version, settings_schema)
 *    - settings_schema에 JSON 아님 입력
 *    - 타입이 맞지 않는 값 (code에 숫자, version에 null 등)
 *    - 아무 필드도 전달하지 않는 빈 body
 * 3. 각 케이스에서 400 validation 에러가 발생함을 TestValidator.error로 검증
 * 4. 정상 입력 update는 성공적으로 갱신되는지도 추가로 검증
 */
export async function test_api_aiShopmall_pluginModules_test_update_plugin_module_with_invalid_data(
  connection: api.IConnection,
) {
  // 1. 정상 플러그인 등록
  const validModule = await api.functional.aiShopmall.pluginModules.post(
    connection,
    {
      body: {
        code: `test_mod_${RandomGenerator.alphaNumeric(6)}`,
        name: "Test Plugin",
        description: "테스트용 플러그인",
        version: "1.0.0",
        settings_schema: '{"type":"object","properties":{}}',
      } satisfies aiShopmallPluginModule.ICreate,
    },
  );
  typia.assert(validModule);
  const moduleId = validModule.id;

  // 2. 잘못된 update 시도 및 유효성 에러 검증
  // (1) 필수 string값, 빈 문자열 전달
  TestValidator.error("빈 code")(() =>
    api.functional.aiShopmall.pluginModules.putById(connection, {
      id: moduleId,
      body: { code: "" },
    }),
  );
  TestValidator.error("빈 name")(() =>
    api.functional.aiShopmall.pluginModules.putById(connection, {
      id: moduleId,
      body: { name: "" },
    }),
  );
  TestValidator.error("빈 version")(() =>
    api.functional.aiShopmall.pluginModules.putById(connection, {
      id: moduleId,
      body: { version: "" },
    }),
  );
  TestValidator.error("빈 settings_schema")(() =>
    api.functional.aiShopmall.pluginModules.putById(connection, {
      id: moduleId,
      body: { settings_schema: "" },
    }),
  );

  // (2) settings_schema에 JSON이 아닌 임의 문자열 입력
  TestValidator.error("settings_schema가 JSON이 아님")(() =>
    api.functional.aiShopmall.pluginModules.putById(connection, {
      id: moduleId,
      body: { settings_schema: "notJson" },
    }),
  );

  // (3) 필드 타입 불일치
  TestValidator.error("code가 숫자")(() =>
    api.functional.aiShopmall.pluginModules.putById(connection, {
      id: moduleId,
      body: { code: 1234 as any },
    }),
  );
  TestValidator.error("version=null")(() =>
    api.functional.aiShopmall.pluginModules.putById(connection, {
      id: moduleId,
      body: { version: null as any },
    }),
  );

  // (4) 빈 body
  TestValidator.error("빈 body")(() =>
    api.functional.aiShopmall.pluginModules.putById(connection, {
      id: moduleId,
      body: {},
    }),
  );

  // 3. 정상 입력 update는 성공
  const updated = await api.functional.aiShopmall.pluginModules.putById(
    connection,
    {
      id: moduleId,
      body: {
        name: "플러그인 이름 수정",
        description: "설명도 변경",
        version: "1.0.1",
        settings_schema: '{"type":"object","properties":{"foo":{"type":"string"}}}',
      },
    },
  );
  typia.assert(updated);
  TestValidator.equals("이름변경")(updated.name)("플러그인 이름 수정");
  TestValidator.equals("버전변경")(updated.version)("1.0.1");
}

