import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopmallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallConfiguration";
import type { aiShopmallPluginModule } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopmallPluginModule";

/**
 * Validate prevention of deleting plugin modules that are actively referenced by configurations.
 *
 * This test attempts to delete a plugin module that is being referenced in a configuration entry, simulating an active dependency scenario.
 * The system should block the deletion, returning a failure status (success=false) and an error message indicating the presence of dependencies.
 *
 * Steps:
 * 1. Register a new plugin module (aiShopmall.pluginModules.post).
 * 2. Create a configuration that references the plugin module (aiShopmall.configurations.post).
 *    - The configuration's value field uses the plugin's code to simulate the dependency.
 * 3. Attempt to delete the plugin module (aiShopmall.pluginModules.eraseById).
 * 4. Assert that deletion fails (success=false) and the error message references dependency or usage.
 */
export async function test_api_aiShopmall_test_delete_plugin_module_in_use(
  connection: api.IConnection,
) {
  // 1. Register a new plugin module
  const pluginInput = {
    code: RandomGenerator.alphabets(10),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.paragraph()(),
    version: "1.0.0",
    settings_schema: "{}",
  } satisfies aiShopmallPluginModule.ICreate;
  const plugin = await api.functional.aiShopmall.pluginModules.post(connection, {
    body: pluginInput,
  });
  typia.assert(plugin);

  // 2. Create a configuration that references the plugin module (simulate usage)
  const configInput = {
    code: `ENABLE_${plugin.code.toUpperCase()}`,
    value: plugin.code,
    description: `Activate plugin ${plugin.code} in system.`,
  } satisfies IAiShopmallConfiguration.ICreate;
  const config = await api.functional.aiShopmall.configurations.post(connection, {
    body: configInput,
  });
  typia.assert(config);

  // 3. Attempt to delete the actively referenced plugin module
  const result = await api.functional.aiShopmall.pluginModules.eraseById(connection, {
    id: plugin.id,
  });
  typia.assert(result);
  TestValidator.equals("plugin module deletion should fail when in use")(result.success)(false);
  TestValidator.predicate("error message should indicate dependency or usage")(
    typeof result.message === "string" &&
      /depend|reference|usage|in use|active|cannot|fail/i.test(result.message),
  );
}

