 *
 * 여러 configuration 엔트리를 다양한 code, channel_id, section_id, value 조합으로 생성한 후,
 * 코드, 채널, 값 등 주어진 필터와 페이지네이션, 정렬 조건으로 PATCH /aiShopmall/configurations
 * 엔드포인트가 정상 동작하는지 검증합니다.
 *
 * 1. code, channel_id, section_id, value의 조합을 다르게 하여 7개의 구성 엔트리를 생성합니다.
 * 2. code 기준, 혹은 channel_id+value 기준으로 필터와 페이징, 정렬 옵션을 다르게 하여 목록을 조회합니다.
 * 3. 반환 데이터가 필터 조건에 맞는지, data length가 예상범위인지, 정렬 및 페이징이 정확히 동작하는지 확인합니다.
 */
export async function test_api_aiShopmall_test_list_configurations_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. 테스트 데이터: 다양한 조합으로 설정 엔트리 7개 생성
  const configs = await ArrayUtil.asyncRepeat(7)(async (i) => {
    const code = `FEATURE_${i % 3}_${RandomGenerator.alphabets(3)}`;
    const value = i % 2 === 0 ? "enabled" : "disabled";
    const channel_id = i % 2 === 0 ? typia.random<string & tags.Format<"uuid">>() : null;
    const section_id = i % 3 === 0 ? typia.random<string & tags.Format<"uuid">>() : null;
    const description = RandomGenerator.paragraph()();

    const config = await api.functional.aiShopmall.configurations.post(connection, {
      body: {
        code,
        value,
        channel_id,
        section_id,
        description,
      } satisfies IAiShopmallConfiguration.ICreate,
    });
    typia.assert(config);
    return config;
  });

  // 2. 필터 기준 선택(실제 생성 결과 활용)
  const filterCode = configs[1].code;
  const filterChannelId = configs[1].channel_id;
  const filterValue = configs[1].value;
  const PAGE_LIMIT = 3;

  // 2-1. code 필터, pagination 적용
  const resByCode = await api.functional.aiShopmall.configurations.patch(connection, {
    body: {
      code: filterCode,
      pagination: {
        page: 1,
        limit: PAGE_LIMIT,
      },
      sort: "created_at",
      order: "asc",
    } satisfies IAiShopmallConfiguration.IRequest,
  });
  typia.assert(resByCode);
  const byCodeExpected = configs.filter(c => c.code === filterCode);
  TestValidator.equals("code필터 data length")(resByCode.data.length)(byCodeExpected.length <= PAGE_LIMIT ? byCodeExpected.length : PAGE_LIMIT);
  resByCode.data.forEach(cfg => {
    TestValidator.equals("code 필터값 일치")(cfg.code)(filterCode);
  });

  // 2-2. channel_id+value 필터, 정렬 desc
  const resByChannelValue = await api.functional.aiShopmall.configurations.patch(connection, {
    body: {
      channel_id: filterChannelId ?? undefined,
      value: filterValue,
      pagination: {
        page: 1,
        limit: PAGE_LIMIT,
      },
      sort: "created_at",
      order: "desc",
    } satisfies IAiShopmallConfiguration.IRequest,
  });
  typia.assert(resByChannelValue);
  resByChannelValue.data.forEach(cfg => {
    if (filterChannelId != null)
      TestValidator.equals("channel_id 필터값 일치")(cfg.channel_id)(filterChannelId);
    TestValidator.equals("value 필터값 일치")(cfg.value)(filterValue);
  });

  // 3. desc 정렬(최신값 우선 정렬) 확인
  const createdAts = resByChannelValue.data.map(cfg => cfg.created_at);
  const sorted = [...createdAts].sort((a, b) => b.localeCompare(a));
  TestValidator.equals("created_at 내림차순 정렬")(createdAts)(sorted);
}

