import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopmallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallConfiguration";

/**
 * 동일한 코드와 스코프(글로벌, 채널, 섹션) 내 중복 설정 레코드 생성 실패(Conflict) 검증
 *
 * ai_shopmall_configurations 구성 테이블은 동일 스코프 내 code가 유일해야 합니다.
 * 본 테스트는 특정 code와 스코프로 최초 설정을 정상 생성 후, 같은 code/scope로 다시 생성 시도 시
 * 정책에 따라 409(CONFLICT) 오류가 발생하여 중복 생성이 불가함을 검증합니다.
 *
 * [테스트 시나리오]
 * 1. 특정 code("DUPLICATE_CODE")와 글로벌 스코프(channel_id/section_id==null)로 설정 생성
 * 2. 같은 code, 같은 글로벌 스코프로 중복 생성 시도
 * 3. 두 번째 요청에서 시스템이 409(CONFLICT) 오류 발생 및 추가 엔트리 생성이 불가함을 검증
 */
export async function test_api_aiShopmall_test_create_configuration_with_duplicate_code_in_scope(
  connection: api.IConnection,
) {
  // 1. 최초 글로벌 범위로 code="DUPLICATE_CODE" 생성
  const configBase = {
    code: "DUPLICATE_CODE",
    value: "true",
    description: "중복 코드/스코프 테스트용 (글로벌)",
    channel_id: null,
    section_id: null,
  } satisfies IAiShopmallConfiguration.ICreate;

  const firstResult = await api.functional.aiShopmall.configurations.post(connection, { body: configBase });
  typia.assert(firstResult);
  TestValidator.equals("정상 등록된 code 확인")(firstResult.code)(configBase.code);
  TestValidator.equals("글로벌 범위 channel_id==null 확인")(firstResult.channel_id)(null);
  TestValidator.equals("글로벌 범위 section_id==null 확인")(firstResult.section_id)(null);

  // 2. 같은 code/스코프로 중복 생성 요청 → 반드시 409 CONFLICT 발생
  const dupConfig = {
    code: "DUPLICATE_CODE",
    value: "false",
    description: "두 번째(중복) 생성 요청",
    channel_id: null,
    section_id: null,
  } satisfies IAiShopmallConfiguration.ICreate;

  await TestValidator.error("동일 코드/스코프 중복 등록은 409 오류 발생해야 함")(
    () => api.functional.aiShopmall.configurations.post(connection, { body: dupConfig })
  );
}

