 * 관리자가 기존에 등록된 설정(Configuration) 엔트리의 value, code, description 필드를 정상적으로 수정할 수 있음을 확인합니다. 테스트는 다음 단계로 수행됩니다.
 *
 * 1. 임의의 유니크 code, value, description 값으로 구성 레코드를 생성합니다. (POST /aiShopmall/configurations)
 * 2. 해당 레코드의 id를 기반으로, value/code/description 필드를 새로운 값으로 PUT 업데이트합니다.
 * 3. 응답 객체에서 id 일치, 변경 필드 정상 반영, created_at 불변성, updated_at은 갱신되었는지 검증합니다.
 *
 * 내부 감사/로깅, 파급효과 등은 API 반환값으로 노출되지 않으므로 이 테스트 대상에서 제외됩니다.
 */
export async function test_api_aiShopmall_configurations_test_update_configuration_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 임의 구성 레코드 생성
  const initialCode = `CODE_${RandomGenerator.alphaNumeric(6)}`;
  const initialValue = RandomGenerator.alphaNumeric(12);
  const initialDescription = RandomGenerator.paragraph()();
  const configuration = await api.functional.aiShopmall.configurations.post(connection, {
    body: {
      code: initialCode,
      value: initialValue,
      description: initialDescription,
      channel_id: null,
      section_id: null,
    } satisfies IAiShopmallConfiguration.ICreate,
  });
  typia.assert(configuration);

  // 2. 변경 데이터 준비
  const newCode = `CODE_${RandomGenerator.alphaNumeric(8)}`;
  const newValue = `${RandomGenerator.alphaNumeric(8)}-updated`;
  const newDescription = RandomGenerator.paragraph()();
  const beforeUpdatedAt = configuration.updated_at;
  const beforeCreatedAt = configuration.created_at;

  // 3. 구성 레코드 업데이트
  const updated = await api.functional.aiShopmall.configurations.putById(connection, {
    id: configuration.id,
    body: {
      code: newCode,
      value: newValue,
      description: newDescription,
    } satisfies IAiShopmallConfiguration.IUpdate,
  });
  typia.assert(updated);

  // 4. 업데이트 결과 검증
  TestValidator.equals("id 일치")(updated.id)(configuration.id);
  TestValidator.equals("code 변경 반영")(updated.code)(newCode);
  TestValidator.equals("value 변경 반영")(updated.value)(newValue);
  TestValidator.equals("description 변경 반영")(updated.description)(newDescription);
  TestValidator.equals("created_at(불변)")(updated.created_at)(beforeCreatedAt);
  TestValidator.notEquals("updated_at은 반드시 갱신됨")(updated.updated_at)(beforeUpdatedAt);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopmallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallConfiguration";

/**
 * Validate that configuration code uniqueness is enforced within the same scope when updating.
 *
 * Business Context:
 * Each configuration (ai_shopmall_configurations) record must have a unique code (key) within its scope (global/channel_id/section_id).
 * This test ensures that attempting to update a configuration's code to one that already exists in the same scope causes a 409 Conflict error.
 *
 * Steps:
 * 1. Create a configuration record (config1) in a given scope (using the POST endpoint), with codeA.
 * 2. Create a second configuration record (config2) in the same scope, with codeB.
 * 3. Attempt to update config2's code to codeA (by calling PUT endpoint with config2.id and changing its code to codeA), leaving all other fields valid and unchanged.
 * 4. Confirm that the system responds with a 409 conflict error (TestValidator.error), proving duplication is not allowed.
 */
export async function test_api_aiShopmall_configurations_test_update_configuration_with_duplicate_code_in_scope(connection: api.IConnection) {
  // 1. Create first configuration in the intended scope
  const scope: {
    channel_id?: string | null;
    section_id?: string | null;
  } = {
    channel_id: typia.random<string & tags.Format<"uuid">>(),
    section_id: null,
  };

  const config1 = await api.functional.aiShopmall.configurations.post(connection, {
    body: {
      channel_id: scope.channel_id,
      section_id: scope.section_id,
      code: "DUPLICATE_TEST_A",
      value: "anyval-a",
      description: "config code A for conflict test",
    } satisfies IAiShopmallConfiguration.ICreate,
  });
  typia.assert(config1);

  // 2. Create a second configuration in the same scope with a different code
  const config2 = await api.functional.aiShopmall.configurations.post(connection, {
    body: {
      channel_id: scope.channel_id,
      section_id: scope.section_id,
      code: "DUPLICATE_TEST_B",
      value: "anyval-b",
      description: "config code B for conflict test",
    } satisfies IAiShopmallConfiguration.ICreate,
  });
  typia.assert(config2);

  // 3. Attempt to update the second config's code to be the same as the first
  await TestValidator.error("409 on duplicate code update")(
    async () => {
      await api.functional.aiShopmall.configurations.putById(connection, {
        id: config2.id,
        body: {
          code: config1.code,
          value: config2.value,
          description: config2.description ?? null,
        } satisfies IAiShopmallConfiguration.IUpdate,
      });
    },
  );
}

