import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { aiShopmallFile } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopmallFile";

/**
 * 파일 메타데이터를 파일 UUID로 정상적으로 조회하는 성공 시나리오를 검증합니다.
 *
 * - 필수 선행조건: 파일이 시스템에 이미 업로드 및 등록되어 있어야 함.
 * - 파일 메타데이터에는 uri, name, size, mime_type, created_at, updated_at 등 모든 주요 정보가 포함되어야 함을 확인합니다.
 *
 * 1. 파일 업로드/등록 API로 신규 파일을 등록한다.
 * 2. 새로 등록된 파일 id(UUID)를 획득한다.
 * 3. 해당 파일 id로 파일 메타데이터 조회 API를 호출한다.
 * 4. 반환된 메타데이터의 모든 주요 필드값이 생성 시 입력값과 일치하는지, 타임스탬프 등의 유효성도 함께 검증한다.
 */
export async function test_api_aiShopmall_files_getById(
  connection: api.IConnection,
) {
  // 1. 파일 업로드(신규 파일 등록)
  const fileInput = {
    uri: `test-upload/${RandomGenerator.alphaNumeric(16)}`,
    name: `테스트파일_${RandomGenerator.alphaNumeric(5)}.png`,
    size: typia.random<number & tags.Type<"int32">>(),
    mime_type: "image/png"
  } satisfies aiShopmallFile.ICreate;
  const created = await api.functional.aiShopmall.files.post(connection, {
    body: fileInput,
  });
  typia.assert(created);

  // 2. 업로드한 파일 UUID로 메타데이터 조회
  const output = await api.functional.aiShopmall.files.getById(connection, {
    id: created.id,
  });
  typia.assert(output);

  // 3. 각 메타데이터 필드값 검증
  TestValidator.equals("id")(output.id)(created.id);
  TestValidator.equals("uri")(output.uri)(fileInput.uri);
