 *
 * 1. 파일을 정상적으로 업로드(등록)한다 (POST /aiShopmall/files)
 * 2. 다른 권한(혹은 인증되지 않은) connection(사용자/세션)으로 파일 메타 정보를 GET /aiShopmall/files/{id}로 조회 시도한다
 * 3. 권한 거부/permisson denied 에러가 발생하는지 확인한다
 * - 파일 존재 및 UUID 형식이 유효한 상태에서 권한 부족만 검증하는 것이 목적이므로, 반드시 파일 생성자를 구분하거나, 별도의 인증 세션에서 시도해야 함
 * - 예상 결과: API에서 접근 거부 혹은 403 Forbidden/권한 오류 발생
 */
export async function test_api_aiShopmall_files_getById_with_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. 파일을 업로드하여 파일의 UUID를 확보한다
  const createdFile: aiShopmallFile = await api.functional.aiShopmall.files.post(
    connection,
    {
      body: {
        uri: RandomGenerator.alphabets(24),
        name: RandomGenerator.alphaNumeric(12),
        size: typia.random<number & tags.Type<"int32">>(),
        mime_type: "application/pdf",
      } satisfies aiShopmallFile.ICreate,
    },
  );
  typia.assert(createdFile);

  // 2. 별도 세션(권한이 없는 사용자 혹은 인증되지 않은 커넥션)으로 파일 메타 정보를 조회 시도
  //    (본 테스트에서는 connection 객체를 복제하며 Authorization 헤더를 삭제해 미인증 상태를 시뮬레이션)
  const unauthorizedConnection = {
    ...connection,
    headers: Object.fromEntries(
      Object.entries(connection.headers ?? {}).filter(
        ([k]) => k.toLowerCase() !== "authorization",
      ),
    ),
  };

  // 3. 권한 부족으로 오류가 발생해야 함
  await TestValidator.error("권한 없는 파일 조회시 오류 발생")(() =>
    api.functional.aiShopmall.files.getById(unauthorizedConnection, { id: createdFile.id }),
  );
}

