 * 비즈니스 플로우:
 * 1. 임의의 uri(스토리지 경로/키), 파일명(name), MIME 타입, 사이즈를 갖는 파일 메타데이터를 생성하여 POST 전송
 * 2. 신규 파일이 등록되어 성공적으로 aiShopmallFile 엔티티가 반환되는지 확인
 * 3. 반환된 파일 메타데이터(특히 uri, name, size, mime_type 등)가 입력값과 일치하는지 검증
 * 4. 파일 식별자(id) 등 주요 값이 올바른 포맷, 타입인지 typia.assert로 체크
 *
 * ※ 본 시나리오는 파일 등록 직후, GET이나 목록 API로의 조회까지 확장 가능하지만 본 API 정의 상 등록(POST) 동작만 검증합니다.
 */
export async function test_api_aiShopmall_files_post(
  connection: api.IConnection,
) {
  // 1. 업로드할 파일 메타데이터 정의 (uri, name, size, mime_type 등)
  const fileInput: aiShopmallFile.ICreate = {
    uri: `unit-test-upload://${RandomGenerator.alphaNumeric(12)}`,
    name: `테스트파일_${RandomGenerator.alphaNumeric(6)}.txt`,
    size: typia.random<number & tags.Type<"int32"> & tags.Minimum<100> & tags.Maximum<10000000>>(),
    mime_type: "text/plain",
  };

  // 2. 파일 업로드 요청 및 정상 반환 확인
  const result: aiShopmallFile = await api.functional.aiShopmall.files.post(
    connection,
    { body: fileInput },
  );
  typia.assert(result);

  // 3. 반환 메타데이터의 주요 속성 검증 (입력값과 일치하는지)
  TestValidator.equals("uri 일치")(result.uri)(fileInput.uri);
  TestValidator.equals("name 일치")(result.name)(fileInput.name);
  TestValidator.equals("size 일치")(result.size)(fileInput.size);
  TestValidator.equals("mime_type 일치")(result.mime_type)(fileInput.mime_type);
  TestValidator.predicate("id가 uuid인지 확인")(typeof result.id === "string" && /^[0-9a-f\-]{36}$/i.test(result.id));
  TestValidator.predicate("created_at이 ISO 8601 date-time")(!!Date.parse(result.created_at));
  TestValidator.predicate("updated_at이 ISO 8601 date-time")(!!Date.parse(result.updated_at));
}

