import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { aiShopmallFile } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopmallFile";

/**
 * 파일 메타데이터 갱신 유효성 및 동작 검증
 *
 * 파일 메타정보(이름, MIME 타입, URI 등)는 업로드 이후에도 관리자가 업데이트할 필요가 있음. 이 테스트 시나리오는 사용 권한이 있는 사용자가 파일 메타데이터를 정상적으로 변경할 수 있는지 검증한다.
 *
 * 사전 준비로 테스트용 파일을 등록한 뒤, PUT /aiShopmall/files/:id 엔드포인트를 이용해 이름, mime_type, uri 중 하나 이상의 속성 값을 변경한다. 변경 이후 반환된 파일 객체가 요청값과 일치하는지 확인하고, 동일 값을 두 번 연달아 업데이트했을 때 idempotency(멱등성)가 보장되는지(즉, 중복 변경이 추가 효과를 내지 않는지) 확인한다. 또한 갱신 직후 단건 조회(read)를 통해 실제 메타데이터가 저장/반영됐는지도 검증해야 한다.
 *
 * 1. 파일 업로드/생성(POST)로 신규 파일 준비 (dependencies)
 * 2. PUT 파일 메타데이터 변경 요청 (name, mime_type, uri 일부 랜덤 변경)
 * 3. 반환 결과의 갱신 내용이 의도대로 반영됐는지 검증
 * 4. 동일 변경값으로 한 번 더 PUT 호출(멱등성 테스트)
 * 5. PUT 응답값이 이전 결과와 동일한지 확인
 * 6. (선택) 단건 read(GET)로도 변경된 정보가 일치하는지 검증
 */
export async function test_api_aiShopmall_files_test_update_file_metadata_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. 파일 업로드/생성: 최초 파일 레코드 준비
  const original = await api.functional.aiShopmall.files.post(connection, {
    body: {
      uri: RandomGenerator.alphaNumeric(32),
      name: RandomGenerator.alphaNumeric(12) + '.png',
      size: typia.random<number & tags.Type<'int32'>>(),
      mime_type: 'image/png',
    } satisfies aiShopmallFile.ICreate,
  });
  typia.assert(original);

  // 2. 메타데이터(이름, MIME, URI) 일부만 변경하는 update 입력값 준비
  const updateInput = {
    name: RandomGenerator.alphaNumeric(16) + '.jpg',
    mime_type: 'image/jpeg',
    uri: RandomGenerator.alphaNumeric(40),
  } satisfies aiShopmallFile.IUpdate;

  // 3. PUT - 파일 메타데이터 일부 변경
  const updated = await api.functional.aiShopmall.files.putById(connection, {
    id: original.id,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals('name')(updated.name)(updateInput.name);
  TestValidator.equals('mime_type')(updated.mime_type)(updateInput.mime_type);
  TestValidator.equals('uri')(updated.uri)(updateInput.uri);
  TestValidator.equals('size(불변)')(updated.size)(original.size);

  // 4. PUT 멱등성: 동일 내용으로 한 번 더 호출해도 결과 일치해야 함
  const updated2 = await api.functional.aiShopmall.files.putById(connection, {
    id: original.id,
    body: updateInput,
