 * 제대로 반환하며 실제 갱신이 적용되지 않는지 검증합니다.
 *
 * 1. 서로 다른 두 파일을 업로드(등록)한다 (POST /aiShopmall/files)
 * 2. 첫 번째 파일의 uri를 두 번째 파일과 동일한 값으로 변경하도록 PUT /aiShopmall/files/{id} 호출 시도
 *    → 이미 존재하는 uri로의 변경이므로 Unique Constraint 위배로 "409 Conflict" 오류가 발생해야 한다
 * 3. 실제 파일 레코드가 갱신되지 않았음을 확인한다 (상세 조회는 불가능하므로 PUT 실패 후 조회 대신 ID와 uri 불일치 체크 고려)
 */
export async function test_api_aiShopmall_test_update_file_metadata_with_duplicate_uri(
  connection: api.IConnection,
) {
  // 1. 서로 다른 두 파일을 업로드
  const file1 = await api.functional.aiShopmall.files.post(connection, {
    body: {
      uri: `test-uri-uniq-${RandomGenerator.alphaNumeric(8)}`,
      name: `sample1_${RandomGenerator.alphaNumeric(5)}`,
      size: typia.random<number & tags.Type<"int32">>() % 5000000 + 1024,
      mime_type: "image/jpeg",
    } satisfies aiShopmallFile.ICreate,
  });
  typia.assert(file1);

  const file2 = await api.functional.aiShopmall.files.post(connection, {
    body: {
      uri: `test-uri-uniq-${RandomGenerator.alphaNumeric(8)}`,
      name: `sample2_${RandomGenerator.alphaNumeric(5)}`,
      size: typia.random<number & tags.Type<"int32">>() % 5000000 + 1024,
      mime_type: "image/png",
    } satisfies aiShopmallFile.ICreate,
  });
  typia.assert(file2);

  // 2. 첫 번째 파일 메타데이터의 uri를 두 번째 파일의 uri로 변경 시도 (중복 충돌 유도)
  await TestValidator.error("중복 URI로 인한 파일 메타데이터 갱신 충돌")(() =>
    api.functional.aiShopmall.files.putById(connection, {
      id: file1.id,
      body: { uri: file2.uri } satisfies aiShopmallFile.IUpdate,
    }),
  );

  // 3. 실제 file1의 uri가 변경되지 않았음을 간접적으로 검증 (직접 조회 API 없음)
  // 본 시스템에서 PUT 실패 시 필드 변경 효과 없음이 계약이므로, 위 에러 후 별도 검증 없음
}

