/**
 * 파일 참조가 없는 파일을 정상적으로 삭제할 수 있는지 검증하는 테스트입니다.
 *
 * - 비즈니스 시나리오: 첨부 등에서 아무도 참조하지 않는 상태의 파일은 삭제가 가능해야 합니다. 올바른 권한으로 삭제 요청 시 실제로 파일이 삭제되고, 이후 해당 파일을 다시 삭제하거나 조회하면 존재하지 않아야 합니다.
 *
 * [단계별 테스트]
 * 1. 새로운 파일을 업로드하여 참조가 없는 파일을 준비합니다.
 * 2. 준비한 파일 id로 삭제(Delete) API를 호출합니다.
 * 3. 성공 응답(success=true)을 확인합니다.
 * 4. 같은 파일 id로 또다시 삭제 시도를 하면 에러가 발생하는지 확인합니다.
 *   (※ 파일 상세조회 GET/lists API가 제공된다면, 삭제 이후 조회 시 not found 에러도 테스트할 수 있습니다. 현재는 DELETE만 검증함)
 */
export async function test_api_aiShopmall_test_delete_file_with_no_references(
  connection: api.IConnection,
) {
  // 1. 참조 없는 테스트용 파일 생성(업로드)
  const file = await api.functional.aiShopmall.files.post(connection, {
    body: {
      uri: `test-uri/${typia.random<string>()}`,
      name: `test-file-${typia.random<string>()}.txt`,
      size: 1234,
      mime_type: "text/plain",
    } satisfies aiShopmallFile.ICreate,
  });
  typia.assert(file);

  // 2. 해당 파일 id로 삭제 API 호출 (권한 적합 가정)
  const delRes = await api.functional.aiShopmall.files.eraseById(connection, {
    id: file.id,
  });
  typia.assert(delRes);
  TestValidator.equals("파일 정상 삭제됨")(delRes.success)(true);

  // 3. 이미 삭제된 파일을 다시 삭제 시도하면 에러 발생 확인
  await TestValidator.error("이미 삭제된 파일 재삭제시 에러")(
    async () => {
      await api.functional.aiShopmall.files.eraseById(connection, {
        id: file.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopmallAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallAttachment";
import type { aiShopmallFile } from "@ORGANIZATION/PROJECT-api/lib/structures/aiShopmallFile";

/**
 * 파일이 첨부(attachment) 등에서 참조 중일 때, 해당 파일을 삭제 시도할 경우의 동작 검증
 *
 * 파일 무결성 정책에 따라 첨부(attachment) 등에서 참조되고 있는 파일을 삭제할 경우, 실제 삭제가 허용되지 않고,
 * 성공 플래그(false)와 함께 참조 중임을 안내하는 진단 메시지가 반환되어야 함을 확인합니다.
 *
 * [테스트 절차]
 * 1. 파일을 새로 업로드(생성)한다.
 * 2. 해당 파일을 첨부(attachment) 엔티티에서 참조하도록 연결한다.
 * 3. 참조 중인 파일을 삭제 시도한다.
 * 4. 시스템이 삭제를 거부(success=false)하고, 메시지에 참조(referenced) 관련 안내가 들어있는지 검증한다.
 */
export async function test_api_aiShopmall_files_test_delete_file_with_active_references(
  connection: api.IConnection,
) {
  // 1. 파일 신규 업로드(생성)
  const file = await api.functional.aiShopmall.files.post(connection, {
    body: {
      uri: `test:///test/${RandomGenerator.alphaNumeric(10)}`,
      name: `테스트파일_${RandomGenerator.alphabets(5)}.png`,
      size: 1024,
      mime_type: "image/png",
    } satisfies aiShopmallFile.ICreate,
  });
  typia.assert(file);

  // 2. 파일을 참조하는 첨부(attachment) 생성
  const attachment = await api.functional.aiShopmall.attachments.post(connection, {
    body: {
      file_id: file.id,
      entity_type: "PRODUCT",
      entity_id: typia.random<string & tags.Format<"uuid">>(),
      name: "테스트 첨부",
      version: 1,
    } satisfies IAiShopmallAttachment.ICreate,
  });
  typia.assert(attachment);

  // 3. 참조 중인 파일 삭제 시도
  const deleteResult = await api.functional.aiShopmall.files.eraseById(connection, {
    id: file.id,
  });
  typia.assert(deleteResult);

  // 4. 성공 플래그 및 진단 메시지 검증: 삭제가 거부되어야 한다
  TestValidator.equals("참조 중 파일 삭제 불가")(deleteResult.success)(false);
  TestValidator.predicate("진단 메시지에 참조(referenced) 안내 포함")(
    typeof deleteResult.message === "string" &&
      deleteResult.message.length > 0 &&
      (deleteResult.message.includes("참조") || deleteResult.message.toLowerCase().includes("reference"))
  );
}

