  let pageSize = 2;
  const listA = await api.functional.aiShopmall.sections.patch(connection, {
    body: { channel_id: channelA.id, pagination: { page: 1, limit: pageSize } },
  });
  typia.assert(listA);
  TestValidator.predicate("channelA 섹션만 추출됨")(
    listA.data.every((s) => s.channel_id === channelA.id)
  );
  TestValidator.equals("page 당 개수 일치")(
    listA.data.length
