  )(3);

  // 4. code 일부('CART')/name 일부('장바구니') 부분검색 검증
  const searchByCode = await api.functional.aiShopmall.sections.patch(connection, {
    body: { code: "CART", pagination: { page: 1, limit: 10 } },
  });
  typia.assert(searchByCode);
  TestValidator.predicate("code에 'CART' 포함된 섹션만")(
    searchByCode.data.every((s) => s.code.includes("CART"))
  );
  const searchByName = await api.functional.aiShopmall.sections.patch(connection, {
    body: { name: "장바구니", pagination: { page: 1, limit: 10 } },
  });
  typia.assert(searchByName);
  TestValidator.predicate("name에 '장바구니' 포함된 섹션만")(
    searchByName.data.every((s) => s.name.includes("장바구니"))
  );

  // 5. 페이징: 2페이지 요청해 일관성 검증
  const listB_page2 = await api.functional.aiShopmall.sections.patch(connection, {
    body: { channel_id: channelB.id, pagination: { page: 2, limit: 2 } },
  });
