  TestValidator.equals("총 레코드 개수 일치")(
    listB_page2.pagination.records
  )(3);

  // 6. sort/order = code desc
  const sorted = await api.functional.aiShopmall.sections.patch(connection, {
    body: { channel_id: channelB.id, sort: "code", order: "desc", pagination: { page: 1, limit: 3 } },
  });
  typia.assert(sorted);
  const codes = sorted.data.map((s) => s.code);
  const sortedCodes = [...codes].sort((a, b) => b.localeCompare(a));
  TestValidator.equals("코드 정렬(desc)")(codes)(sortedCodes);

  // 7. 반환 summary 구조 검증
  TestValidator.predicate("summary 필드만 존재")(
    sorted.data.every((s) => (
      Object.keys(s).sort().join(",") === [
        "id",
        "channel_id",
        "code",
        "name",
        "created_at",
        "updated_at",
      ].sort().join(",")
    ))
  );
}

