 * 1. Create a channel (with random code, name)
 * 2. Create a section in that channel (random section code and name)
 * 3. Attempt section creation with same code (different name) in the same channel → Validate 409 conflict
 * 4. Attempt section creation with different code but same name in the same channel → Validate 409 conflict
 * 5. Attempt section creation in another new channel using same code and name as the first section → Should succeed
 */
export async function test_api_aiShopmall_test_create_section_duplicate_code_name_per_channel_conflict(
  connection: api.IConnection,
) {
