    code: RandomGenerator.alphabets(6),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.content()()(),
  };
  const channel = await api.functional.aiShopmall.channels.post(connection, { body: channelInput });
  typia.assert(channel);

  // 2. Create an initial section under channel
  const sectionInput: IAiShopmallSection.ICreate = {
