  // 3. Attempt to create a section with same code, different name in same channel - expect conflict
  const dupeCodeInput: IAiShopmallSection.ICreate = {
    channel_id: channel.id,
    code: sectionInput.code,
    name: RandomGenerator.paragraph()(1) + "-DIFF", // ensure different name
    description: RandomGenerator.content()()(),
  };
  await TestValidator.error("duplicate section code per channel should fail")(
