  const section2 = await api.functional.aiShopmall.sections.post(connection, {
    body: {
      channel_id: channel2.id,
      code: sectionInput.code,
      name: sectionInput.name,
      description: RandomGenerator.content()()(),
    },
  });
  typia.assert(section2);
}

