import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopmallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallChannel";
import type { IAiShopmallSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallSection";

/**
 * AI Shopmall의 섹션명(name) 및 설명(description) 성공 수정 플로우
 *
 * - 이 테스트는 Section(섹션) 엔터티의 name, description 필드 업데이트를 검증합니다.
 * - 사전 준비로서, 채널(Channel) 생성 → 해당 채널에 섹션 생성 → 섹션 ID로 name/description 변경 요청 흐름을 이행합니다.
 * - 응답값의 둘 필드가 정상 업데이트되었는지, 기타 속성(코드/채널/타임스탬프 등)은 일관 보존되는지 확인합니다.
 * - 일반적 권한/제약조건(예: 관리자 전용, 접근제어)은 자동 테스트 환경에서 암묵 보장됨.
 * - 감사 로그 기록 점검은 API 자체가 비즈니스 정책상 내장되어 있음을 전제(확인 API 별도 없음).
 *
 * [시나리오 단계]
 * 1. 테스트 전용 채널을 생성한다
 * 2. 방금 만든 채널에 소속된 섹션을 생성한다
 * 3. 해당 section의 id로 name/description 필드만 새로운 값으로 수정한다
 * 4. 응답에서 name/description이 정상 반영됐는지, code/channel/created_at 등 주요 정보는 일관성 유지되는지 검증한다
 * 5. (비가시적) 접근권한, 감사로그 등은 서비스 환경 및 사업규칙상 API 내부적으로 처리
 */
export async function test_api_aiShopmall_test_update_section_name_and_description_success(connection: api.IConnection) {
  // 1. 채널을 생성한다
  const channelInput: IAiShopmallChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.paragraph()(1),
  };
  const channel = await api.functional.aiShopmall.channels.post(connection, { body: channelInput });
  typia.assert(channel);

  // 2. 생성된 채널에 섹션 엔터티를 만든다
  const sectionInput: IAiShopmallSection.ICreate = {
    channel_id: channel.id,
    code: RandomGenerator.alphaNumeric(8),
    name: "초기명칭",
    description: "초기 설명"
  };
  const section = await api.functional.aiShopmall.sections.post(connection, { body: sectionInput });
  typia.assert(section);
  TestValidator.equals("section 채널 ID 일치")(section.channel_id)(channel.id);

  // 3. 해당 section id로 name/description 필드만 수정
  const updateInput: IAiShopmallSection.IUpdate = {
    name: "수정된 섹션명",
    description: "수정된 섹션 설명"
  };
  const updated = await api.functional.aiShopmall.sections.putById(connection, { id: section.id, body: updateInput });
  typia.assert(updated);

  // 4. 응답 결과 검증: 필드 변경/불변 속성 체크
  TestValidator.equals("name이 정상 반영됨")(updated.name)(updateInput.name);
  TestValidator.equals("description이 정상 반영됨")(updated.description)(updateInput.description);
  TestValidator.equals("id 불변")(updated.id)(section.id);
  TestValidator.equals("code 불변")(updated.code)(section.code);
  TestValidator.equals("channel_id 불변")(updated.channel_id)(section.channel_id);
  TestValidator.equals("created_at 불변")(updated.created_at)(section.created_at);
  TestValidator.predicate("updated_at 정상 변경됨")(updated.updated_at > section.updated_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopmallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallChannel";
import type { IAiShopmallSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallSection";

/**
 * 동일 채널 내 섹션 name 중복 업데이트(충돌) 시도 시 409 오류(Conflict) 발생을 검증하는 테스트입니다.
 *
 * 채널과 2개의 섹션(sectionA, sectionB)을 신규 생성한 뒤, sectionA의 name을 sectionB와 동일하게 덮어쓰는 업데이트를 시도하면
 * API가 올바르게 409 충돌(Conflict)을 반환해야 하며, 데이터베이스 유니크 정책/비즈니스 정책이 정상 동작함을 확인합니다.
 *
 * step-by-step:
 * 1. 테스트용 채널 1개 등록
 * 2. 동일 채널에 sectionA, sectionB 2개 생성 (서로 다른 name/code)
 * 3. sectionA의 name을 sectionB의 name으로 업데이트(중복) 시도 → 409 오류 검증
 * 4. 반대로 sectionB를 sectionA의 name으로 중복 업데이트 시도 → 409 오류 검증
 *
 * IUpdate DTO로는 code 수정이 불가능하므로 name 기준만 테스트합니다.
 */
export async function test_api_aiShopmall_test_update_section_conflict_duplicate_code_or_name(connection: api.IConnection) {
  // 1. 테스트용 채널 생성
  const channel = await api.functional.aiShopmall.channels.post(connection, {
    body: {
      code: `CH${Date.now()}`,
      name: `Test Channel ${Date.now()}`,
      description: "테스트용 채널",
    } satisfies IAiShopmallChannel.ICreate,
  });
  typia.assert(channel);

  // 2. sectionA, sectionB 생성 (서로 다른 name/code)
  const sectionA = await api.functional.aiShopmall.sections.post(connection, {
    body: {
      channel_id: channel.id,
      code: `SEC_A_${Date.now()}`,
      name: `SectionA_${Date.now()}`,
      description: "테스트 sectionA",
    } satisfies IAiShopmallSection.ICreate,
  });
  typia.assert(sectionA);

  const sectionB = await api.functional.aiShopmall.sections.post(connection, {
    body: {
      channel_id: channel.id,
      code: `SEC_B_${Date.now()}`,
      name: `SectionB_${Date.now()}`,
      description: "테스트 sectionB",
    } satisfies IAiShopmallSection.ICreate,
  });
  typia.assert(sectionB);

  // 3. sectionA의 name을 sectionB의 name으로 변경(중복) 시도 → 409 오류 기대
  await TestValidator.error("sectionA의 name을 sectionB와 중복 업데이트 시도: 409")(
    async () => {
      await api.functional.aiShopmall.sections.putById(connection, {
        id: sectionA.id,
        body: {
          name: sectionB.name,
          description: sectionA.description ?? undefined,
        } satisfies IAiShopmallSection.IUpdate,
      });
    }
  );

  // 4. sectionB를 sectionA의 name으로 중복 업데이트 시도 → 409 오류 기대
  await TestValidator.error("sectionB를 sectionA의 name으로 중복 업데이트 시도: 409")(
    async () => {
      await api.functional.aiShopmall.sections.putById(connection, {
        id: sectionB.id,
        body: {
          name: sectionA.name,
          description: sectionB.description ?? undefined,
        } satisfies IAiShopmallSection.IUpdate,
      });
    }
  );
}

