import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopmallSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallSection";

/**
 * 잘못된 요청 바디로 섹션 정보(IAiShopmallSection) 수정 시도 시 400 Validation 오류 발생을 검증합니다.
 *
 * → name이 너무 짧거나(빈 문자열), 너무 긴 경우
 * → description에 타입이 올바르지 않은 값(숫자, 배열, 객체, boolean 등) 전달 시
 *
 * TypeScript 타입 시스템으로 작성 불가(컴파일 에러 발생)하는 케이스(ex. name:number 등)는 E2E 테스트에서 구현하지 않습니다. 실제 테스트에서는 런타임에 400 Validation이 발생 가능한 요청만 검증합니다.
 *
 * 각 invalid input에 대해 putById 호출 시 반드시 400 오류가 발생해야 합니다.
 *
 * 1. name이 빈 문자열 (""),
 * 2. name이 너무 길 때(300자),
 * 3. description이 숫자형,
 * 4. description이 배열,
 * 5. description이 객체,
 * 6. description이 boolean 타입,
 */
export async function test_api_aiShopmall_test_update_section_invalid_input(
  connection: api.IConnection,
) {
  // 테스트에 사용할 유효한 UUID
  const sectionId = typia.random<string & tags.Format<"uuid">>();

  // 1. name이 빈 문자열
  await TestValidator.error("name이 빈 문자열 - 400 오류 기대")(() =>
    api.functional.aiShopmall.sections.putById(connection, {
      id: sectionId,
      body: {
        name: "",
        description: "desc",
      } satisfies IAiShopmallSection.IUpdate,
    })
  );

  // 2. name이 너무 길 때 (300자)
  await TestValidator.error("name이 너무 길 때 - 400 오류 기대")(() =>
    api.functional.aiShopmall.sections.putById(connection, {
      id: sectionId,
      body: {
        name: "A".repeat(300),
        description: null,
      } satisfies IAiShopmallSection.IUpdate,
    })
  );

  // 3. description이 숫자형 (as unknown as ... 사용)
  await TestValidator.error("description이 숫자일 때 - 400 오류 기대")(() =>
    api.functional.aiShopmall.sections.putById(connection, {
      id: sectionId,
