/**
 * 참조/종속 데이터가 전혀 없는 섹션을 정상적으로 삭제할 수 있는지 검증합니다.
 *
 * - 사전 생성된 채널에 소속된 섹션을 1개 만들고, 별도 참조 엔터티는 생성하지 않습니다.
 * - 삭제 API(`/aiShopmall/sections/{id}`)를 호출하여 삭제가 정상 반영되는지 확인합니다.
 * - 삭제 응답에 삭제된 객체 주요 필드가 정확히 반환되는지 검증합니다.
 * - 삭제 직후 재조회 및 Audit 로그 API는 미제공이므로 생략합니다.
 *
 * 순서:
 * 1. 채널 생성 (section 소속용)
 * 2. 해당 채널에 섹션 1개 생성 (삭제 대상)
 * 3. 삭제 API 호출로 section 제거
 * 4. 삭제 응답 내 id, channel_id, code, name 필드 일치 검증
 */
export async function test_api_aiShopmall_sections_test_delete_section_success_when_no_references(
  connection: api.IConnection,
) {
  // 1. 채널 생성
  const channel = await api.functional.aiShopmall.channels.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
    } satisfies IAiShopmallChannel.ICreate,
  });
  typia.assert(channel);

  // 2. 채널 소속 섹션 1개 생성
  const section = await api.functional.aiShopmall.sections.post(connection, {
    body: {
      channel_id: channel.id,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
    } satisfies IAiShopmallSection.ICreate,
  });
  typia.assert(section);

  // 3. 삭제 API 호출 (존재하는 섹션, 참조 없음 가정)
  const deleted = await api.functional.aiShopmall.sections.eraseById(connection, { id: section.id });
  typia.assert(deleted);

  // 4. 삭제 응답 주요 필드 동일성 검증
  TestValidator.equals("deleted id")(deleted.id)(section.id);
  TestValidator.equals("deleted channel_id")(deleted.channel_id)(channel.id);
  TestValidator.equals("deleted code")(deleted.code)(section.code);
  TestValidator.equals("deleted name")(deleted.name)(section.name);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
