import type { IAiShopmallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallConfiguration";

/**
 * 설정(구성)에 의해 참조 중인 섹션 삭제 시 409 Conflict 오류 발생 검증
 *
 * 비즈니스 목적:
 * - 섹션(Section)이 설정(Configuration)에 의해 참조되고 있을 경우, 삭제가 불가능하며 409 Conflict 오류가 반환되어야 함을 검증
 * - 데이터 참조 관계에 의한 무결성 정책 및 잘못된 삭제 시도 내역의 감사 대응에 부합
 *
 * 절차:
 * 1. 새로운 채널 생성 (sections가 소속될 상위 엔티티)
 * 2. 채널에 소속되는 새로운 섹션 생성
 * 3. 해당 섹션을 section_id로 참조하는 configuration(구성) 생성
 * 4. 참조 중인 섹션 삭제 시도: 409 Conflict 오류 발생 확인 (TestValidator.error 활용)
 */
export async function test_api_aiShopmall_test_delete_section_with_existing_references_conflict(
  connection: api.IConnection,
) {
  // 1. 신규 채널 생성
  const channel = await api.functional.aiShopmall.channels.post(connection, {
    body: {
      code: `CHAN-${RandomGenerator.alphaNumeric(8)}`,
      name: `테스트채널-${RandomGenerator.alphaNumeric(4)}`,
      description: "e2e section 참조충돌 테스트 전용 채널",
    } satisfies IAiShopmallChannel.ICreate,
  });
  typia.assert(channel);

  // 2. 채널 내 new 섹션 생성
  const section = await api.functional.aiShopmall.sections.post(connection, {
    body: {
      channel_id: channel.id,
      code: `SEC-${RandomGenerator.alphaNumeric(8)}`,
      name: `테스트섹션-${RandomGenerator.alphaNumeric(4)}`,
      description: "e2e 참조 충돌 테스트용 section",
    } satisfies IAiShopmallSection.ICreate,
  });
  typia.assert(section);

  // 3. 위 섹션을 section_id로 참조하는 configuration insert
  const config = await api.functional.aiShopmall.configurations.post(connection, {
    body: {
      channel_id: channel.id,
      section_id: section.id,
      code: `CFG-REF-${RandomGenerator.alphaNumeric(6)}`,
      value: "true",
      description: "test section ref configuration",
    } satisfies IAiShopmallConfiguration.ICreate,
  });
  typia.assert(config);

  // 4. 섹션 삭제 시도(구성에 참조 중): 409에러 발생해야 함
  await TestValidator.error("configuration에 참조중인 섹션 삭제 시 conflict error 반환")(
    async () => {
      await api.functional.aiShopmall.sections.eraseById(connection, {
        id: section.id,
      });
    },
  );
}

