import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopmallAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallAttachment";

/**
 * 첨부파일 상세 단건 조회 기능 검증.
 *
 * - 첨부 레코드를 하나 신규로 생성(post)한 뒤,
 * - 생성 결과 반환된 id를 활용해 getById(첨부 단건조회)를 호출하고,
 * - 반환된 상세 데이터의 전체 필드(file_id, entity_type, entity_id, name, version, created_at, updated_at 등)가 생성값과 일치하는지 assert 한다.
 * 이로써 단건 조회 API의
 * 1) 정확한 조회, 2) 메타데이터 반환, 3) 관리자 권한 요구(별도 인증 플로우 없으므로 액세스만 검증)
 *를 종합 검증.
 *
 * [검증 절차]
 * 1. 첨부 생성 API로 레코드 신규작성 → 반환 id 확보
 * 2. getById로 단건상세 조회
 * 3. 상세결과의 전체 필드가 생성값/생성결과와 정확히 일치하는지 assert
 * 4. 오류/엣지케이스: 임의 uuid로 요청시 not-found 동작 확인 (별도 주요 실패케이스 확인)
 */
export async function test_api_aiShopmall_test_retrieve_attachment_detail_with_valid_id(
  connection: api.IConnection,
) {
  // 1. 첨부파일 엔터티 신규 생성
  const createInput: IAiShopmallAttachment.ICreate = {
    file_id: typia.random<string & tags.Format<"uuid">>(),
    entity_type: "PRODUCT",
    entity_id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.alphaNumeric(10),
    version: 1,
  };
  const created: IAiShopmallAttachment = await api.functional.aiShopmall.attachments.post(connection, { body: createInput });
  typia.assert(created);

  // 2. 단건 상세 조회 getById: 반환 id로 호출
  const detail: IAiShopmallAttachment = await api.functional.aiShopmall.attachments.getById(connection, { id: created.id });
  typia.assert(detail);

  // 3. 모든 주요 필드가 생성값/생성결과와 일치하는지 확인
  TestValidator.equals("id 일치")(detail.id)(created.id);
  TestValidator.equals("file_id 일치")(detail.file_id)(createInput.file_id);
  TestValidator.equals("entity_type 일치")(detail.entity_type)(createInput.entity_type);
  TestValidator.equals("entity_id 일치")(detail.entity_id)(createInput.entity_id);
  TestValidator.equals("name 일치")(detail.name)(createInput.name);
  TestValidator.equals("version 일치")(detail.version)(createInput.version);
  // created_at, updated_at 필드는 DB/서비스 관점 timestamp 이므로 "존재/형식" 여부 확인 정도만 추가.
  TestValidator.predicate("created_at 필수/exist")(typeof detail.created_at === "string" && detail.created_at.length > 0);
  TestValidator.predicate("updated_at 필수/exist")(typeof detail.updated_at === "string" && detail.updated_at.length > 0);

  // 4. NotFound 등 오류/엣지케이스: 존재하지 않는 임의 uuid로 요청 시 정상 에러 응답
  await TestValidator.error("존재하지 않는 첨부 id → not found")(async () => {
    await api.functional.aiShopmall.attachments.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
  });
}

