/**
 * Validate business rules and conflict scenarios for attachment creation.
 *
 * This test ensures the aiShopmall attachment creation endpoint correctly enforces:
 * - Duplicate association conflicts (should return 409)
 * - Reference integrity (nonexistent file_id, invalid entity_type/ID)
 *
 * Steps:
 * 1. Create a valid file for use as an attachment
 * 2. Create a valid attachment associating that file to a business entity
 * 3. Attempt to create a duplicate attachment (should error)
 * 4. Attempt with a nonexistent file_id (should error)
 * 5. Attempt with an invalid entity_type (should error)
 * 6. Attempt with an invalid entity_id (should error)
 */
export async function test_api_aiShopmall_test_create_attachment_with_duplicate_or_conflicting_data(
  connection: api.IConnection,
) {
  // 1. Create a valid file
  const file = await api.functional.aiShopmall.files.post(connection, {
    body: {
      uri: RandomGenerator.alphabets(12),
      name: RandomGenerator.alphabets(8) + ".pdf",
      size: 4096,
      mime_type: "application/pdf",
    } satisfies aiShopmallFile.ICreate,
  });
  typia.assert(file);

  // 2. Create a valid attachment
  const entity_type = "PRODUCT";
  const entity_id = typia.random<string & tags.Format<"uuid">>();
  const name = "상품첨부파일1";
  const version = 1;
  const attachment = await api.functional.aiShopmall.attachments.post(connection, {
    body: {
      file_id: file.id,
      entity_type,
      entity_id,
      name,
      version,
    } satisfies IAiShopmallAttachment.ICreate,
  });
  typia.assert(attachment);

  // 3. Attempt to create a duplicate attachment (should fail: 409 Conflict)
  await TestValidator.error("duplicate attachment should fail")(() =>
    api.functional.aiShopmall.attachments.post(connection, {
      body: {
        file_id: file.id,
        entity_type,
        entity_id,
        name,
        version,
      } satisfies IAiShopmallAttachment.ICreate,
    })
  );

  // 4. Attempt to create an attachment with a nonexistent file_id (should error)
  await TestValidator.error("nonexistent file_id should fail")(() =>
    api.functional.aiShopmall.attachments.post(connection, {
      body: {
        file_id: typia.random<string & tags.Format<"uuid">>(), // random not-in-table id
        entity_type,
        entity_id,
        name: name + "-file",
        version,
      } satisfies IAiShopmallAttachment.ICreate,
    })
  );

  // 5. Attempt to create an attachment with an invalid entity_type
  await TestValidator.error("invalid entity_type should fail")(() =>
    api.functional.aiShopmall.attachments.post(connection, {
      body: {
        file_id: file.id,
        entity_type: "INVALID_TYPE",
        entity_id,
        name,
        version,
      } satisfies IAiShopmallAttachment.ICreate,
    })
  );

  // 6. Attempt to create an attachment with an invalid entity_id
  await TestValidator.error("invalid entity_id should fail")(() =>
    api.functional.aiShopmall.attachments.post(connection, {
      body: {
        file_id: file.id,
        entity_type,
        entity_id: typia.random<string & tags.Format<"uuid">>(), // random unrelated id
        name: name + "-entity",
        version,
      } satisfies IAiShopmallAttachment.ICreate,
    })
  );
}

