import type { IAiShopmallAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallAttachment";

/**
 * 첨부파일 메타데이터 수정(정상 입력값)의 엔드 투 엔드 테스트.
 *
 * - 비즈니스: 시스템 관리자가 첨부파일(논리명, 파일, 소속/대상 엔터티, 버전 등)에 대해 부분/전체 정보를 변경하는 기능 검증.
 *   정상 입력값에 대한 변경 시도와 결과 반영 여부를 하나씩 단계적으로 확인한다.
 *   (audit log, admin 권한 등 정책은 API/GW 이슈로 본 테스트에서는 주석 확인만 수행함)
 *
 * [검증 시나리오]
 * 1. 첨부파일을 한 건 생성(POST)하여 테스트 대상 ID 확보
 * 2. 각각 name, file_id, entity_type, entity_id, version 단일 필드를 개별 갱신(PUT)
 *    - 각 스텝별 응답값에서 실제 변경 항목이 바르게 반영됐는지 assertion
 * 3. 그 이후 한 번에 여러 필드 동시 갱신(Multi-field PUT) 정상 동작 확인
 *    - 예시: name/file_id/version 등을 조합
 * 4. 각 업데이트마다 updated_at이 전 단계 대비 상승(갱신)됐는지도 함께 점검
 * 5. (불가영역) audit log 기록 여부, 관리자 권한 체크 등은 별도 시스템/GW에서 처리됨을 주석으로 명시
 */
export async function test_api_aiShopmall_attachments_test_update_attachment_metadata_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 첨부파일 생성 (테스트 주체 ID 획득)
  const initialAttachment = await api.functional.aiShopmall.attachments.post(connection, {
    body: {
      file_id: typia.random<string & tags.Format<"uuid">>(),
      entity_type: "PRODUCT",
      entity_id: typia.random<string & tags.Format<"uuid">>(),
      name: "Initial Attachment Name",
      version: 1,
    } satisfies IAiShopmallAttachment.ICreate,
  });
  typia.assert(initialAttachment);

  // 2. [단일필드] name 갱신
  const updatedName = "수정된 논리명_A";
  const nameUpdate = await api.functional.aiShopmall.attachments.putById(connection, {
    id: initialAttachment.id,
    body: { name: updatedName } satisfies IAiShopmallAttachment.IUpdate,
  });
  typia.assert(nameUpdate);
  TestValidator.equals("name 변경")(nameUpdate.name)(updatedName);
  TestValidator.predicate("updated_at 변동")(nameUpdate.updated_at !== initialAttachment.updated_at);

  // 3. [단일필드] file_id 갱신
  const newFileId = typia.random<string & tags.Format<"uuid">>();
  const fileIdUpdate = await api.functional.aiShopmall.attachments.putById(connection, {
    id: initialAttachment.id,
    body: { file_id: newFileId } satisfies IAiShopmallAttachment.IUpdate,
  });
  typia.assert(fileIdUpdate);
  TestValidator.equals("file_id 변경")(fileIdUpdate.file_id)(newFileId);
  TestValidator.predicate("updated_at 변동")(fileIdUpdate.updated_at !== nameUpdate.updated_at);

  // 4. [단일필드] entity_type 갱신
  const newEntityType = "REVIEW";
  const entityTypeUpdate = await api.functional.aiShopmall.attachments.putById(connection, {
    id: initialAttachment.id,
    body: { entity_type: newEntityType } satisfies IAiShopmallAttachment.IUpdate,
  });
  typia.assert(entityTypeUpdate);
  TestValidator.equals("entity_type 변경")(entityTypeUpdate.entity_type)(newEntityType);
  TestValidator.predicate("updated_at 변동")(entityTypeUpdate.updated_at !== fileIdUpdate.updated_at);

  // 5. [단일필드] entity_id 갱신
  const newEntityId = typia.random<string & tags.Format<"uuid">>();
  const entityIdUpdate = await api.functional.aiShopmall.attachments.putById(connection, {
    id: initialAttachment.id,
    body: { entity_id: newEntityId } satisfies IAiShopmallAttachment.IUpdate,
  });
  typia.assert(entityIdUpdate);
  TestValidator.equals("entity_id 변경")(entityIdUpdate.entity_id)(newEntityId);
  TestValidator.predicate("updated_at 변동")(entityIdUpdate.updated_at !== entityTypeUpdate.updated_at);

  // 6. [단일필드] version 갱신
  const newVersion = 2;
  const versionUpdate = await api.functional.aiShopmall.attachments.putById(connection, {
    id: initialAttachment.id,
    body: { version: newVersion } satisfies IAiShopmallAttachment.IUpdate,
  });
  typia.assert(versionUpdate);
  TestValidator.equals("version 변경")(versionUpdate.version)(newVersion);
  TestValidator.predicate("updated_at 변동")(versionUpdate.updated_at !== entityIdUpdate.updated_at);

  // 7. [복수필드] 동시에 name/file_id/version 갱신
  const multiUpdate: IAiShopmallAttachment.IUpdate = {
    name: "멀티필드수정",
    file_id: typia.random<string & tags.Format<"uuid">>(),
    version: 3,
  };
  const multiFieldUpdate = await api.functional.aiShopmall.attachments.putById(connection, {
    id: initialAttachment.id,
    body: multiUpdate,
  });
  typia.assert(multiFieldUpdate);
  TestValidator.equals("name multi 변경")(multiFieldUpdate.name)(multiUpdate.name);
  TestValidator.equals("file_id multi 변경")(multiFieldUpdate.file_id)(multiUpdate.file_id);
  TestValidator.equals("version multi 변경")(multiFieldUpdate.version)(multiUpdate.version);
  TestValidator.predicate("updated_at 변동")(multiFieldUpdate.updated_at !== versionUpdate.updated_at);

  // 8. (참고) 감사로그/권한: 본 테스트에서는 별도 검증 불가(주석 명시)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
