import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopmallAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallAttachment";

/**
 * 첨부파일의 업데이트 입력 무결성 제약 및 중복 제약을 검증한다.
 *
 * 본 테스트는 ai_shopmall_attachments에 대해 다음 시나리오를 검증한다:
 *
 * 1. 첨부파일을 정상적으로 등록한다 (file_id, entity_type, entity_id, name, version 모두 정상)
 * 2. 동일 entity_type + entity_id + name + version 조합으로 갱신 시도 -> 409 Conflict
 * 3. file_id를 누락하거나 잘못된 값으로 갱신 시도 -> 400 Bad Request
 * 4. entity_id/entity_type에 무효값(존재하지 않거나 포맷만 맞는 랜덤 uuid/값)으로 갱신 시도 -> 400 Bad Request
 * 5. 각 에러 시도 후에도 원본 attachment가 변경되지 않았음을 불변성으로 확인한다
 *
 * 이 테스트는 입력 제약/무결성/불변 기준 검증을 통해 API의 안정성과 신뢰도를 확인한다.
 */
export async function test_api_aiShopmall_test_update_attachment_with_conflicting_or_invalid_input(
  connection: api.IConnection,
) {
  // 1. 정상 첨부파일 생성
  const baseAttachment = await api.functional.aiShopmall.attachments.post(connection, {
    body: {
      file_id: typia.random<string & tags.Format<"uuid">>(),
      entity_type: "PRODUCT",
      entity_id: typia.random<string & tags.Format<"uuid">>(),
      name: "상품설명이미지",
      version: 1,
    } satisfies IAiShopmallAttachment.ICreate
  });
  typia.assert(baseAttachment);

