import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopmallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallChannel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIAiShopmallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiShopmallChannel";

/**
 * E2E 테스트: AI Shopmall 채널 페이징/필터/정렬 목록 조회 (관리자 기준, 다양한 검색 조건 및 페이징, 정렬 검증)
 *
 * 비즈니스 목적: 관리자 권한으로 6개의 AI Shopmall 채널을 고유한 코드/이름/설명으로 생성한 뒤,
 * 다양한 필터(code, name, description)와 페이지네이션, 정렬(asc/desc) 조건을 조합해 목록 API 응답이
 * 기대한 결과(필터링, 서브셋, 정렬, 페이징, 빈 결과 등)를 정확히 반환하는지 검증한다. 비관리자 접근 제한, 감사로그 등은 구현 불가시 생략.
 *
 * 테스트 절차:
 * 1. 테스트용 prefix 적용(코드: FILTERTEST001~006, name/description 다양화) 채널 6건 생성
 * 2. code prefix로 전체검색 및 정렬/전체 서브셋 일치
 * 3. name 단일조건 검색(정확 1건 매치)
 * 4. description 기준 일부 서브셋(3건)
 * 5. 페이지네이션/정렬(page 2, limit 2, code 오름순), 해당 page row 정확 매칭
 * 6. 존재하지 않는 필터 코드로 빈 결과 확인
 */
export async function test_api_aiShopmall_test_list_channels_with_filter_and_pagination_valid_parameters(
  connection: api.IConnection,
) {
  // 1. 유니크 테스트 채널 6건 생성
  const uniqueChannels = ArrayUtil.repeat(6)((idx) => ({
    code: `FILTERTEST${(idx + 1).toString().padStart(3, "0")}`,
    name: `테스트${String.fromCharCode(65 + idx)}`,
    description: idx % 2 === 0 ? `설명A${idx}` : `설명B${idx}`,
  }));

  for (const channel of uniqueChannels) {
    const created = await api.functional.aiShopmall.channels.post(connection, {
      body: channel satisfies IAiShopmallChannel.ICreate,
    });
    typia.assert(created);
    TestValidator.equals("code 일치")(created.code)(channel.code);
    TestValidator.equals("name 일치")(created.name)(channel.name);
    TestValidator.equals("description 일치")(created.description ?? null)(channel.description ?? null);
  }

  // 2. 코드 prefix 필터로 전체 매칭, 정렬확인
  {
    const filterPrefix = "FILTERTEST00";
    const output = await api.functional.aiShopmall.channels.patch(connection, {
      body: {
        code: filterPrefix,
        pagination: { page: 1, limit: 10 },
        sort: "code",
        order: "asc",
      } satisfies IAiShopmallChannel.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("전체 6건 반환")(output.data.length)(6);
    TestValidator.equals("pagination.records")(output.pagination.records)(6);
    TestValidator.equals("pagination.current")(output.pagination.current)(1);
    TestValidator.equals("pagination.limit")(output.pagination.limit)(10);
    for(let i = 0; i < 6; ++i) {
      TestValidator.equals(`code 정렬: idx${i}`)(output.data[i].code)(uniqueChannels[i].code);
    }
  }

  // 3. 이름 기준 단일 condition (테스트A)
  {
    const output = await api.functional.aiShopmall.channels.patch(connection, {
      body: {
        name: "테스트A",
        pagination: { page: 1, limit: 10 },
      } satisfies IAiShopmallChannel.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("정확 1건")(output.data.length)(1);
    TestValidator.equals("name 값")(output.data[0].name)("테스트A");
  }

  // 4. description = "설명A" 포함 row (idx 0,2,4)
  {
    const output = await api.functional.aiShopmall.channels.patch(connection, {
      body: {
        description: "설명A",
        pagination: { page: 1, limit: 10 },
        sort: "created_at",
        order: "desc",
      } satisfies IAiShopmallChannel.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("3건")(output.data.length)(3);
    for(const row of output.data) TestValidator.predicate("desc에 '설명A' 포함")(row.code === "FILTERTEST001" || row.code === "FILTERTEST003" || row.code === "FILTERTEST005");
  }

  // 5. 페이지네이션(page 2, limit 2): 3,4번째, 오름차순
  {
    const output = await api.functional.aiShopmall.channels.patch(connection, {
      body: {
        code: "FILTERTEST00",
        pagination: { page: 2, limit: 2 },
        sort: "code",
        order: "asc",
      } satisfies IAiShopmallChannel.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("2 rows")(output.data.length)(2);
    TestValidator.equals("pagination.current 2")(output.pagination.current)(2);
    TestValidator.equals("page2 idx0=FILTERTEST003")(output.data[0].code)(uniqueChannels[2].code);
    TestValidator.equals("page2 idx1=FILTERTEST004")(output.data[1].code)(uniqueChannels[3].code);
  }

  // 6. 잘못된 code 조건 -> 빈 결과
  {
    const output = await api.functional.aiShopmall.channels.patch(connection, {
      body: {
        code: "존재하지않음",
        pagination: { page: 1, limit: 5 },
      } satisfies IAiShopmallChannel.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("빈 결과")(output.data.length)(0);
    TestValidator.equals("pagination.records=0")(output.pagination.records)(0);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
