import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIAiShopmallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiShopmallChannel";

/**
 * Test channel list API with invalid query parameters and expect validation errors.
 *
 * This test verifies that the /aiShopmall/channels listing endpoint correctly rejects invalid request parameters and returns proper validation errors. The following edge cases are covered:
 *
 * 1. Exceeding the maximum allowed page size (limit).
 * 2. Providing invalid types for filter or pagination fields, such as a string instead of a number, or an object where a string is expected.
 * 3. Using improper sort keys that do not correspond to sortable fields.
 *
 * Each case should ensure the API returns an HTTP 400 Bad Request with appropriate validation error feedback.
 *
 * Steps:
 * 1. Construct a request with pagination.limit set unreasonably high (e.g., 10,000), which should violate max allowed limit if enforced by backend validation.
 * 2. Construct a request with pagination.page as a string instead of number, expecting validation failure.
 * 3. Construct a request with code as an object instead of string.
 * 4. Use a sort key that is not supported (e.g., 'non_existent_field').
 * 5. For each of the above, assert that the API returns a 400 status with a proper error response.
 */
export async function test_api_aiShopmall_test_list_channels_with_invalid_query_parameters(
  connection: api.IConnection,
) {
  // 1. Exceedingly high limit
  await TestValidator.error("limit too high should fail")(async () => {
    await api.functional.aiShopmall.channels.patch(connection, {
      body: {
        pagination: {
          page: 1,
          limit: 10000,
        },
      },
    });
  });

  // 2. Wrong type for pagination.page (string instead of number)
  await TestValidator.error("page as string should fail")(async () => {
    await api.functional.aiShopmall.channels.patch(connection, {
      body: {
        pagination: {
          page: "one" as any,
          limit: 10,
        },
      },
    });
  });

  // 3. Wrong type for code (object instead of string)
  await TestValidator.error("code as object should fail")(async () => {
    await api.functional.aiShopmall.channels.patch(connection, {
      body: {
        code: { unexpected: "field" } as any,
        pagination: {
          page: 1,
          limit: 10,
        },
      },
    });
