  TestValidator.predicate("created_at ISO 8601")(!!Date.parse(channel.created_at));
  TestValidator.predicate("updated_at ISO 8601")(!!Date.parse(channel.updated_at));
  // 4. 불필요 필드 노출 위반 여부 (현재 정의 DTO와 정확히 일치해야 함)
