    description: "Initial description",
  };
  const created = await api.functional.aiShopmall.channels.post(connection, {
    body: createData,
  });
  typia.assert(created);

  // 2~3. 생성 응답값에서 id, code 추출 및 저장
  const channelId = created.id;
  const prevName = created.name;
  const prevDescription = created.description;
  const prevCode = created.code;
  const prevCreatedAt = created.created_at;
  const prevUpdatedAt = created.updated_at;

  // 4. 변경용 name, description 값 준비
  const updateInput: IAiShopmallChannel.IUpdate = {
    name: `Updated Channel Name-${Date.now()}`,
    description: "Updated channel description.",
  };

  // 5. name, description만 변경
  const updated = await api.functional.aiShopmall.channels.putById(connection, {
    id: channelId,
    body: updateInput,
  });
  typia.assert(updated);

  // 6. 변경된 값 검증
  // name, description은 새 값으로 변경. code/created_at은 불변
  TestValidator.equals("업데이트된 name 필드")(updated.name)(updateInput.name);
  TestValidator.equals("업데이트된 description 필드")(updated.description)(updateInput.description);
  TestValidator.equals("code는 변하지 않아야 함")(updated.code)(prevCode);
  TestValidator.equals("created_at도 변하지 않아야 함")(updated.created_at)(prevCreatedAt);
  // updated_at은 반드시 변경되어야 함
  TestValidator.notEquals("updated_at은 변경되어야 함")(updated.updated_at)(prevUpdatedAt);
}

