import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopmallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallChannel";

/**
 * 채널의 유니크 코드(code)가 외부에서 참조되고 있는 상황에서,
 * 해당 코드 값을 가진 다른 채널로 변경 시도가 발생할 때 시스템이
 * 어떻게 동작하는지 검증하는 시나리오입니다.
 *
 * 본 테스트는 레퍼런스 제약조건(Referential Integrity)이
 * code 필드에 적용되어 있고, 연관된 참조가 존재하는 상황을 가정합니다.
 * 
 * **주요 테스트 목표:**
 * - code 필드가 실질적으로 unique임을 시스템에서 검사하는지
 * - 유니크 제약조건 위반 시(예: code, 또는 name 등 중복) 409 Conflict
 *   에러 및 감사 로그 등이 도출되는지 검증함
 *
 * **테스트 단계:**
 * 1. 두 개 이상의 채널(채널A, 채널B)을 생성
 *    - 채널A: code = 'CHANNEL_A', name = 'A', etc.
 *    - 채널B: code = 'CHANNEL_B', name = 'B', etc.
 * 2. 채널A의 정보를 업데이트하며 name을 'B'(채널B와 동일)로 중복 시도
 * 3. 409 Conflict 예외가 발생하는지, 타입 스크립트 예외 타이핑/감사
 * 4. 비고: 현 시점 API 구조상 code 필드는 업데이트 대상이 아님. 추후 확장 시 본래 시나리오로 테스트 구현 전환 필요
 *
 * @note 이 테스트는 실제 "code" 필드 중복 업데이트가 API 구조적으로 불가하므로
 *      "name"(유니크 여부 명확하지 않지만 충돌/Conflict 유도 목적) 중복 상황을 통해서
 *      유니크 제약 위반/409 에러 발생을 대리로 검증합니다.
 */
export async function test_api_aiShopmall_channels_test_update_channel_violating_unique_code_constraint(
  connection: api.IConnection,
) {
  // 1. 두 개 이상의 채널(채널A, 채널B) 생성
  const createA = {
    code: `CHANNEL_A_${typia.random<string>()}`,
    name: `ChannelA_${typia.random<string>()}`,
    description: "채널A 생성용 테스트",
  } satisfies IAiShopmallChannel.ICreate;
  const channelA = await api.functional.aiShopmall.channels.post(connection, { body: createA });
  typia.assert(channelA);

  const createB = {
    code: `CHANNEL_B_${typia.random<string>()}`,
    name: `ChannelB_${typia.random<string>()}`,
    description: "채널B 생성용 테스트",
  } satisfies IAiShopmallChannel.ICreate;
  const channelB = await api.functional.aiShopmall.channels.post(connection, { body: createB });
  typia.assert(channelB);

  // 2. 채널A 정보 업데이트 시도 (name을 채널B와 동일하게 변경, code 필드 업데이트 불가 대응 시나리오)
  //    유니크 제약 있는 필드에 중복 적용 시도 => 409 Conflict 예상
  await TestValidator.error("채널 name(혹은 유니크 필드) 충돌 시 409 Conflict")(
    async () => {
      await api.functional.aiShopmall.channels.putById(connection, {
        id: channelA.id,
        body: {
          name: channelB.name, // 중복 유발
          description: "중복 name(혹은 유니크 필드) 업데이트로 인한 충돌 테스트",
        } satisfies IAiShopmallChannel.IUpdate,
      });
    },
  );
}

