import type { IAiShopmallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallChannel";

/**
 * Validate that updating an AI Shopmall channel entity with invalid input fields results in validation errors (400 Bad Request).
 *
 * 비정상/유효성 위반 데이터로 채널 수정(putById) 시 호출이 400 Bad Request가 발생함을 검증.
 *
 * [테스트 절차]
 * 1. 채널 엔터티를 정상적으로 생성한다 (dependencies 활용).
 * 2. update 시 IUpdate에 overly long name, 빈 name, 너무 긴 description 등 의도적 유효성 위반 케이스로 호출 시도 후 400 오류 발생을 검증한다.
 *    - name에 null 또는 정의에 없는 필드 전달 등 TypeScript로 표현 불가한 케이스는 SKIP(주석 설명)
 *
 * [유의사항]
 * - 실제 필드에 없는 속성(extra property), name: null 형태는 타입 강제상 TypeScript로 전달 불가하므로 코드에서 테스트 불가(주석으로 언급)
 * - 오직 컴파일 가능한 유효성 오류 케이스만 시나리오에 포함
 */
export async function test_api_aiShopmall_channels_test_update_channel_with_invalid_input(
  connection: api.IConnection,
) {
  // 1. Create a valid test channel (dependency)
  const created = await api.functional.aiShopmall.channels.post(connection, {
    body: {
      code: `CHN-${typia.random<string>()}`,
      name: "valid channel",
      description: "test channel",
    } satisfies IAiShopmallChannel.ICreate,
  });
  typia.assert(created);

  // 2-1. Try to update with overly long name
  await TestValidator.error("name too long should fail with 400")(
    () => api.functional.aiShopmall.channels.putById(connection, {
      id: created.id,
      body: {
        name: "A".repeat(1000),
        description: "desc normal",
      } satisfies IAiShopmallChannel.IUpdate,
    })
  );

  // 2-2. Try to update with empty name
  await TestValidator.error("empty name should fail with 400")(
    () => api.functional.aiShopmall.channels.putById(connection, {
      id: created.id,
      body: {
        name: "",
        description: "desc",
      } satisfies IAiShopmallChannel.IUpdate,
    })
  );

  // 2-3. Try to update with overly long description
  await TestValidator.error("description too long should fail with 400")(
    () => api.functional.aiShopmall.channels.putById(connection, {
      id: created.id,
      body: {
        name: "valid name",
        description: "D".repeat(5000),
      } satisfies IAiShopmallChannel.IUpdate,
    })
  );

  // Cannot test: name: null (type error at compilation), or sending extra properties (TypeScript rejection)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
