/**
 * AI Shopmall 채널(Section/Config 참조 없는 상태) 정상 삭제 E2E 검증
 *
 * 비즈니스 요구사항:
 * - 채널이 다른 엔터티에서 참조되지 않은 경우, 정상적으로 삭제(erase) 처리가 되어야 한다.
 * - 삭제 시 해당 채널의 레코드(혹은 삭제 확인 값)가 반환되어야 하며, 감사(Audit) 로그 관점에서 필수 반환 필드가 일치하는지 검사한다.
 *
 * 테스트 프로세스:
 * 1. 참조 없는 테스트용 임시 채널 생성
 * 2. 즉시 해당 채널을 삭제
 * 3. 반환된 값이 삭제 전 생성값과(특히 id/code/name) 완전히 일치하는지 확인
 * 4. 필요시, 추가 조회 등 달리 제공되는 API 없으면 생략
 */
export async function test_api_aiShopmall_channels_test_delete_channel_successful_when_no_references(
  connection: api.IConnection,
) {
  // 1. 참조 없는 테스트 채널 생성 (삭제 바로 가능)
  const input: IAiShopmallChannel.ICreate = {
    code: `TEST-DEL-${RandomGenerator.alphaNumeric(8)}`,
    name: `E2E DeleteCh ${RandomGenerator.alphabets(5)}`,
    description: "E2E 삭제 정상 케이스. 참조 없는 테스트 채널.",
  };
  const created: IAiShopmallChannel = await api.functional.aiShopmall.channels.post(connection, {
    body: input,
  });
  typia.assert(created);

  // 2. 해당 채널을 바로 삭제 시도(실제 참조 없음 전제)
  const deleted: IAiShopmallChannel = await api.functional.aiShopmall.channels.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleted);

  // 3. 반환값이 원래 생성한 레코드와 완전히 일치하는지 검증 (id/code/name)
  TestValidator.equals("삭제 채널 id")(deleted.id)(created.id);
  TestValidator.equals("삭제 채널 code")(deleted.code)(created.code);
  TestValidator.equals("삭제 채널 name")(deleted.name)(created.name);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiShopmallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallChannel";
import type { IAiShopmallSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiShopmallSection";

/**
 * 채널 삭제 시 referential integrity(참조 무결성) 검증 및 409 Conflict 발생 테스트
 *
 * 이 테스트는 아래와 같은 실제 비즈니스 흐름/정합성 검증을 목적으로 한다:
 * 1. 채널을 신규 등록한다.
 * 2. 등록된 채널을 참조하는 섹션을 1개 이상 생성한다(channel_id 사용).
 * 3. 위에서 생성한 채널의 id로 삭제 요청 시도 (DELETE /aiShopmall/channels/{id})
 * 4. 섹션 등에서 해당 채널을 참조 중이므로, 409 Conflict(참조 무결성 충돌) 에러가 발생해야 한다.
 * 5. 결과적으로 삭제 시도가 실패했음을 입증하고, 해당 오류 상황도 감사적으로 로깅되어야 함
 *
 * 실제 현업에서 관리자/설정페이지 등 채널 삭제 UI 구현 시, 연결된 섹션/설정이 있으면 삭제 차단 정책이 유지되어야 하므로, DB의 referential integrity가 필수임을 검증하는 목적.
 *
 * 본 테스트는 정상적인 삭제 실패(409) case만 테스트하며, 성공/비정상 케이스는 타 테스트에서 분리 수행.
 */
export async function test_api_aiShopmall_test_delete_channel_with_references_conflict(
  connection: api.IConnection,
) {
  // 1. 신규 채널을 등록한다.
  const channel = await api.functional.aiShopmall.channels.post(connection, {
    body: {
      code: `TEST-CHANNEL-${RandomGenerator.alphaNumeric(8)}`,
      name: `테스트 채널_${RandomGenerator.alphabets(4)}`,
      description: "참조 무결성 검증용 테스트 채널"
    } satisfies IAiShopmallChannel.ICreate,
  });
  typia.assert(channel);

  // 2. 해당 채널을 참조하는 section을 등록한다.
  const section = await api.functional.aiShopmall.sections.post(connection, {
    body: {
      channel_id: channel.id,
      code: `SEC-${RandomGenerator.alphaNumeric(6)}`,
      name: `테스트섹션_${RandomGenerator.alphabets(4)}`,
      description: "채널 참조 테스트 섹션"
    } satisfies IAiShopmallSection.ICreate,
  });
  typia.assert(section);

  // 3. 채널 삭제 시도 (참조 무결성 위반 상황)
  await TestValidator.error("section 참조 중인 채널 삭제시 409 Conflict")(
    async () => {
      await api.functional.aiShopmall.channels.eraseById(connection, {
        id: channel.id,
      });
    },
  );
}

